// Java foundations, each tied to a file in the CometCarpool backend.
import { lesson, program, checks } from './helpers.mjs';

const J = 'https://dev.java/learn/';
const runMain = 'stdout(() -> Main.main(new String[0]))';

export const core = [

lesson({
  id: 'program', title: 'Classes, main & printing', file: 'BackendApplication.java',
  explanation: ['Every Java program starts in a method named main inside a class.', 'System.out.println prints a value followed by a newline; + joins text and values into one string.'],
  overview: 'Java code lives in classes. The JVM starts your program by calling `public static void main(String[] args)`. CometCarpool\'s `BackendApplication.main` is exactly this method; it hands control to Spring.',
  goals: ['Read the shape of a Java class and its main method.', 'Predict what println prints when text and numbers are joined with +.'],
  diagram: ['From source to output', [['Main.java', 'You write classes in .java files'], ['javac', 'Compiles them to bytecode and reports type errors'], ['java Main', 'The JVM calls Main.main'], ['println', 'Each call prints one line']]],
  sections: [
    ['The outer shell', ['`public class Main` declares a class. Its name must match the file name, Main.java.', '`public static void main(String[] args)` is the entry point. static means no object is needed to call it; void means it returns nothing.'], 'public class Main {\n    public static void main(String[] args) {\n        System.out.println("Hi");\n    }\n}'],
    ['Statements and semicolons', ['Statements run top to bottom and each ends with a semicolon.', 'Braces { } group statements into a class or method body. Indentation is for humans; braces are what Java reads.']],
    ['Joining with +', ['When either side of + is a String, Java joins text: "Seats: " + 3 becomes "Seats: 3".', '+ is evaluated left to right, so 1 + 2 + " seats" adds first (3 seats) while "Ride " + 1 + 2 joins twice (Ride 12).']],
    ['In CometCarpool', ['`BackendApplication.java` has only a main method. It calls `SpringApplication.run(...)`, which starts the web server and every @Service and @RestController.', 'You will see that startup in the Maven & Spring Boot lesson.']],
  ],
  misconception: 'A compile error is not program output. javac rejects the code before main ever runs, so nothing is printed.',
  takeaway: 'A Java program is a class with a main method; println prints one line per call.',
  tryIt: 'Add a third println that prints "Profile: dev" and run the example.',
  example: program('System.out.println("CometCarpool backend starting");\nSystem.out.println("Port: " + 8080);'),
  predict: { code: program('System.out.println("Ride " + 1 + 2);\nSystem.out.println(1 + 2 + " seats");\nSystem.out.print("UTD");\nSystem.out.println("!");'), expected: 'Ride 12\n3 seats\nUTD!\n', explanation: '+ runs left to right. "Ride " + 1 makes text first, so 2 is appended as text. 1 + 2 adds numbers before meeting a String. print does not end the line, so ! lands on the same line.' },
  guided: {
    title: 'Change the startup banner', signature: 'public static void main(String[] args)',
    prompt: 'Change the program so it prints exactly Welcome to CometCarpool on one line.',
    description: 'The starter prints a placeholder message. Change it so the banner reads Welcome to CometCarpool.',
    requirements: ['Print exactly Welcome to CometCarpool followed by a newline.', 'Print nothing else.'],
    examples: [['Run Main.main', 'Welcome to CometCarpool\n'], ['Starter output', 'Hello, learner!\n', 'This is what you are replacing.']], constraints: ['Keep the class named Main.', 'Use System.out.println.'],
    starter: program('System.out.println("Hello, learner!");'),
    reference: program('System.out.println("Welcome to CometCarpool");'),
    tests: checks(`eq("output", "Welcome to CometCarpool\\n", ${runMain});`),
    hints: ['Only the text inside the quotes needs to change.', 'println already adds the newline for you.', 'System.out.println("Welcome to CometCarpool");'],
  },
  practice: {
    title: 'Print a pickup card', signature: 'public static void main(String[] args)',
    prompt: 'Write main so it prints a two-line pickup card: Pickup: Jonsson, then Seats: 3. Build the second line by joining text with the number 3.',
    description: 'Print a two-line pickup card for a ride.',
    requirements: ['Line 1: Pickup: Jonsson', 'Line 2: Seats: 3, built by joining "Seats: " with the int 3.'],
    examples: [['Run Main.main', 'Pickup: Jonsson\nSeats: 3\n', 'Two println calls, one per line.'], ['Wrong: println("Seats: 3")', 'Same text, but the task asks you to join the int 3.']], constraints: ['Exactly two lines of output.'],
    starter: program('// Print the pickup card here.'),
    reference: program('System.out.println("Pickup: Jonsson");\nSystem.out.println("Seats: " + 3);'),
    tests: checks(`eq("output", "Pickup: Jonsson\\nSeats: 3\\n", ${runMain});`),
    hints: ['Each line is its own println call.', 'A String + an int produces a String.', 'System.out.println("Seats: " + 3);'],
  },
  sources: [{ title: 'dev.java: Getting started', url: J + 'getting-started/' }],
}),

lesson({
  id: 'types', title: 'Types, variables & wrapper types', file: 'model/User.java',
  explanation: ['Every Java variable has a fixed type such as int, double, boolean, String, or Long.', 'Primitives (int, long) can never be null; wrapper types (Integer, Long) can, which is why User.id is a Long.'],
  overview: 'A variable is a named box with a fixed type. Java checks types at compile time, so a String box can never hold a number. `User.id` is a `Long` (capital L) so it can be null before the database assigns one.',
  goals: ['Declare and reassign variables of different types.', 'Predict integer division and explain why Long can be null but long cannot.'],
  diagram: ['Two kinds of types', [['Primitive', 'int, long, double, boolean: the raw value, never null'], ['Reference', 'String, Long, User: points to an object or is null'], ['Autoboxing', 'Java converts long <-> Long for you'], ['null id', 'A new User has id null until the DB saves it']]],
  sections: [
    ['Declare, then assign', ['`int seats = 3;` declares a variable with type int and starting value 3.', '`seats = seats - 1;` reassigns it. You only write the type once, at the declaration.'], 'int seats = 3;\nseats = seats - 1; // now 2'],
    ['Integer vs decimal math', ['int / int throws away the remainder: 10 / 4 is 2.', 'If either side is a double, the result is a double: 10 / 4.0 is 2.5. Storing 10 / 4 in a double still gives 2.0, because the division already happened in ints.']],
    ['Wrappers and null', ['`Long id = null;` is legal; `long id = null;` is a compile error.', 'JPA uses null to mean not saved yet. After save, Postgres fills id with 1, 2, 3 and so on.']],
    ['In CometCarpool', ['User has `private Long id; private String email; private String role;`.', 'Strings like firstName also start as null until something sets them.']],
  ],
  misconception: 'double share = 10 / 4; does not give 2.5. The right side is computed in ints first (2), then widened to 2.0.',
  takeaway: 'Types are fixed. Watch for int division, and use wrapper types when "no value yet" (null) must be possible.',
  tryIt: 'Change id to 42L and seats to seats * 2, then predict the output before running.',
  example: program('String email = "ana@utdallas.edu";\nint seats = 3;\nboolean verified = false;\nLong id = null;\nSystem.out.println(email + " " + seats + " " + verified + " " + id);\nseats = seats - 1;\nSystem.out.println(seats);'),
  predict: { code: program('int seats = 4;\nint taken = seats / 3;\ndouble share = 10 / 4;\ndouble exact = 10 / 4.0;\nSystem.out.println(taken + " " + share + " " + exact);\nLong id = 7L;\nSystem.out.println(id + 1);'), expected: '1 2.0 2.5\n8\n', explanation: '4 / 3 is int division, giving 1. 10 / 4 is 2 before it becomes 2.0. 10 / 4.0 uses a double, giving 2.5. A Long unboxes for arithmetic, so 7 + 1 is 8.' },
  guided: {
    title: 'Compute seats left', signature: 'public static void main(String[] args)',
    prompt: 'Change seatsLeft so it is computed from total and booked instead of hard-coded, so the program prints Seats left: 3.',
    description: 'A ride has 4 total seats and 1 booked. seatsLeft is hard-coded to 0. Compute it from the other two variables.',
    requirements: ['seatsLeft must equal total - booked.', 'Print exactly Seats left: 3.'],
    examples: [['total = 4, booked = 1', 'Seats left: 3\n'], ['if total were 5', 'Seats left: 4\n', 'Computed, not hard-coded.']], constraints: ['Do not change total or booked.'],
    starter: program('int total = 4;\nint booked = 1;\nint seatsLeft = 0;\nSystem.out.println("Seats left: " + seatsLeft);'),
    reference: program('int total = 4;\nint booked = 1;\nint seatsLeft = total - booked;\nSystem.out.println("Seats left: " + seatsLeft);'),
    tests: checks(`eq("output", "Seats left: 3\\n", ${runMain});`),
    hints: ['Use the two variables that already exist.', 'Subtraction uses -.', 'int seatsLeft = total - booked;'],
  },
  practice: {
    title: 'Split the gas cost', signature: 'static double splitCost(int gasDollars, int riders)',
    prompt: 'Implement splitCost so it returns each rider\'s exact share of the gas cost as a double, without losing the fractional part.',
    description: 'Riders split the driver\'s gas cost evenly (see P2 question Q19). Return the exact share.',
    requirements: ['Return gasDollars divided by riders as a double.', '10 dollars across 4 riders must give 2.5, not 2.0.'],
    examples: [['splitCost(10, 4)', '2.5'], ['splitCost(12, 4)', '3.0'], ['splitCost(9, 2)', '4.5', 'Avoid int division.']],
    constraints: ['riders is always at least 1.'],
    starter: program('System.out.println(splitCost(10, 4));', { statics: 'static double splitCost(int gasDollars, int riders) {\n    return 0.0;\n}' }),
    reference: program('System.out.println(splitCost(10, 4));', { statics: 'static double splitCost(int gasDollars, int riders) {\n    return (double) gasDollars / riders;\n}' }),
    tests: checks('eq("splitCost(10, 4)", 2.5, Main.splitCost(10, 4));\neq("splitCost(12, 4)", 3.0, Main.splitCost(12, 4));\neq("splitCost(9, 2)", 4.5, Main.splitCost(9, 2));\neq("splitCost(7, 1)", 7.0, Main.splitCost(7, 1));'),
    hints: ['Both parameters are ints, so gasDollars / riders is int division.', 'Make one side a double before dividing.', 'return (double) gasDollars / riders;'],
  },
  sources: [{ title: 'dev.java: Primitive types', url: J + 'language-basics/primitive-types/' }],
}),

lesson({
  id: 'methods', title: 'Methods, parameters & return values', file: 'service/UserService.java',
  explanation: ['A method is a named piece of code with typed parameters and a return type.', 'Java passes copies of primitive arguments, so changing a parameter inside a method does not change the caller\'s variable.'],
  overview: 'Methods name a computation. `static int seatsLeft(int total, int booked)` takes two ints and returns one. UserService is a set of methods: `saveUser(User)`, `loginUser(String, String)`, `getAllUsers()`.',
  goals: ['Declare a method with parameters and a return type.', 'Trace nested calls and explain pass-by-value.'],
  diagram: ['A method call', [['Caller', 'seatsLeft(4, 1)'], ['Parameters', 'total = 4, booked = 1 (copies)'], ['Body', 'Runs until return'], ['Result', 'The call expression becomes 3']]],
  sections: [
    ['Signature anatomy', ['`static int seatsLeft(int total, int booked)` has a modifier, a return type, a name, and parameters.', 'void means nothing is returned. A non-void method must return a value of its type on every path.'], 'static int seatsLeft(int total, int booked) {\n    return total - booked;\n}'],
    ['Calls are expressions', ['`seatsLeft(4, 1)` evaluates to 3, so you can print it, store it, or pass it to another method.', 'Inner calls run first: twice(addOne(2)) computes addOne(2) and then twice of that.']],
    ['Pass by value', ['The method receives a copy of each primitive argument. Reassigning the parameter changes only the copy.', 'Objects are different: the copy is a reference, so the method can change the object\'s fields. You will see this with classes.']],
    ['In CometCarpool', ['`public User loginUser(String email, String password)` returns a User or throws an exception.', '`public List<User> getAllUsers()` takes no parameters and returns a list.']],
  ],
  misconception: 'Printing inside a method is not returning. A method that only prints gives the caller nothing to use.',
  takeaway: 'Parameters bring copies of values in; return sends one value out.',
  tryIt: 'Call printRide with seatsLeft(5, 2) and predict the line before running.',
  example: program('int left = seatsLeft(4, 1);\nprintRide("Ana", left);\nprintRide("Ben", seatsLeft(3, 3));', { statics: 'static int seatsLeft(int total, int booked) {\n    return total - booked;\n}\n\nstatic void printRide(String driver, int left) {\n    System.out.println(driver + ": " + left + " left");\n}' }),
  predict: { code: program('int x = 5;\nint y = addOne(x);\nSystem.out.println(x + " " + y);\nSystem.out.println(twice(addOne(twice(1))));', { statics: 'static int twice(int n) {\n    return n * 2;\n}\n\nstatic int addOne(int n) {\n    n = n + 1;\n    return n;\n}' }), expected: '5 6\n6\n', explanation: 'addOne changes only its copy of n, so x stays 5 while y is 6. Inside out: twice(1) is 2, addOne(2) is 3, and twice(3) is 6.' },
  guided: {
    title: 'Return the full name', signature: 'static String fullName(String first, String last)',
    prompt: 'Change fullName so it returns the first name, a space, and the last name, instead of only the first name.',
    description: 'User has firstName and lastName fields. The starter fullName returns only the first name.',
    requirements: ['Return first + " " + last.'],
    examples: [['fullName("Ana", "Lopez")', '"Ana Lopez"'], ['fullName("Ben", "Ito")', '"Ben Ito"']], constraints: ['Return the value; do not print it.'],
    starter: program('System.out.println(fullName("Ana", "Lopez"));', { statics: 'static String fullName(String first, String last) {\n    return first;\n}' }),
    reference: program('System.out.println(fullName("Ana", "Lopez"));', { statics: 'static String fullName(String first, String last) {\n    return first + " " + last;\n}' }),
    tests: checks('eq("fullName(Ana, Lopez)", "Ana Lopez", Main.fullName("Ana", "Lopez"));\neq("fullName(Ben, Ito)", "Ben Ito", Main.fullName("Ben", "Ito"));'),
    hints: ['Both parameters should appear in the result.', 'Put a " " between them.', 'return first + " " + last;'],
  },
  practice: {
    title: 'Cars needed', signature: 'static int carsNeeded(int students, int seatsPerCar)',
    prompt: 'Implement carsNeeded so it returns the minimum number of cars needed to carry all students, rounding any partial car up.',
    description: 'A study group wants to carpool to campus. Return how many cars they need.',
    requirements: ['Round up: 10 students with 4 seats per car need 3 cars.', '0 students need 0 cars.'],
    examples: [['carsNeeded(10, 4)', '3'], ['carsNeeded(8, 4)', '2', 'Exactly full cars need no extra car.'], ['carsNeeded(1, 4)', '1']],
    constraints: ['students >= 0 and seatsPerCar >= 1.', 'Use int math; no floating point needed.'],
    starter: program('System.out.println(carsNeeded(10, 4));', { statics: 'static int carsNeeded(int students, int seatsPerCar) {\n    return 0;\n}' }),
    reference: program('System.out.println(carsNeeded(10, 4));', { statics: 'static int carsNeeded(int students, int seatsPerCar) {\n    return (students + seatsPerCar - 1) / seatsPerCar;\n}' }),
    tests: checks('eq("carsNeeded(10, 4)", 3, Main.carsNeeded(10, 4));\neq("carsNeeded(8, 4)", 2, Main.carsNeeded(8, 4));\neq("carsNeeded(1, 4)", 1, Main.carsNeeded(1, 4));\neq("carsNeeded(0, 4)", 0, Main.carsNeeded(0, 4));\neq("carsNeeded(7, 7)", 1, Main.carsNeeded(7, 7));'),
    hints: ['students / seatsPerCar rounds down.', 'Rounding up means adding one car when there is a remainder, or adding seatsPerCar - 1 before dividing.', 'return (students + seatsPerCar - 1) / seatsPerCar;'],
  },
  sources: [{ title: 'dev.java: Defining methods', url: J + 'classes-objects/defining-methods/' }],
}),

lesson({
  id: 'conditions', title: 'Conditions, booleans & String methods', file: 'service/UserService.java',
  explanation: ['if/else chooses a branch from a boolean; && and || short-circuit, so later checks can depend on earlier ones.', 'Compare Strings with equals, never ==, and use methods like endsWith, trim, and toLowerCase.'],
  overview: 'UserService rejects non-UTD emails with `if (user.getEmail() == null || !user.getEmail().endsWith("@utdallas.edu"))`. The null check comes first, and || stops early, so endsWith is never called on null.',
  goals: ['Write if/else logic with &&, ||, and !.', 'Use String methods correctly and explain why == is wrong for text.'],
  diagram: ['The UTD email gate', [['email == null?', 'true: reject at once (|| short-circuits)'], ['endsWith("@utdallas.edu")?', 'Only checked when email exists'], ['!', 'Flips: reject when it does NOT end with the domain'], ['Pass', 'Continue to the duplicate check']]],
  sections: [
    ['Branches', ['`if (cond) { ... } else { ... }` runs exactly one branch.', 'A return inside a branch ends the method, so the code below runs only when the condition was false.']],
    ['Combining conditions', ['&& means both must be true; || means at least one. ! negates.', 'Both short-circuit: in a || b, b is skipped when a is true. That is what makes `email == null || email.endsWith(...)` safe.', '&& binds tighter than ||, so a || b && c means a || (b && c).']],
    ['Strings are objects', ['`a.equals(b)` compares the characters. `a == b` asks whether they are the same object, which can be false for equal text.', 'Useful methods: trim(), toLowerCase(), endsWith(x), isBlank(), equalsIgnoreCase(x). Each returns a new value; Strings never change in place.'], 'String e = " Ana@UTDallas.edu ";\ne.trim().toLowerCase(); // "ana@utdallas.edu"'],
    ['In CometCarpool', ['Known issue #9: Foo@utdallas.edu and foo@utdallas.edu count as different users. Normalizing with trim().toLowerCase() fixes it.', 'Normalize once, when the email first enters the service, so stored and looked-up values always match.']],
  ],
  misconception: 'email.endsWith(...) || email == null is not the same check. Order matters: with null, endsWith runs first and throws a NullPointerException.',
  takeaway: 'Put null checks first, compare text with equals, and normalize user input before comparing.',
  tryIt: 'Call check with "ANA@UTDALLAS.EDU" and predict the result. Why does it fail?',
  example: program('System.out.println(check("ana@utdallas.edu"));\nSystem.out.println(check("ana@gmail.com"));\nSystem.out.println(check(null));', { statics: 'static String check(String email) {\n    if (email == null || !email.endsWith("@utdallas.edu")) {\n        return "rejected";\n    }\n    return "accepted";\n}' }),
  predict: { code: program('String a = "Ana@UTDallas.edu";\nSystem.out.println(a.endsWith("@utdallas.edu"));\nSystem.out.println(a.toLowerCase().endsWith("@utdallas.edu"));\nString b = "  ben@utdallas.edu ";\nSystem.out.println(b.trim().equals("ben@utdallas.edu"));\nSystem.out.println("ride".equals("RIDE") || 3 > 2 && false);'), expected: 'false\ntrue\ntrue\nfalse\n', explanation: 'endsWith is case-sensitive. Lowercasing first makes it match. trim removes the outer spaces. && runs before ||: (3 > 2 && false) is false, and "ride".equals("RIDE") is false too.' },
  guided: {
    title: 'Accept any capitalization', signature: 'static boolean isUtdEmail(String email)',
    prompt: 'Change isUtdEmail so emails with different capitalization or surrounding spaces are still accepted, while null and non-UTD emails are rejected.',
    description: 'The starter only accepts exact lowercase input (known issue #9). Normalize the email before checking it.',
    requirements: ['Return false for null.', 'Ignore surrounding spaces and letter case.', 'The address must end with @utdallas.edu after normalizing.'],
    examples: [['isUtdEmail("Ana@UTDALLAS.EDU")', 'true'], ['isUtdEmail(" ben@utdallas.edu ")', 'true'], ['isUtdEmail("utdallas.edu@gmail.com")', 'false']],
    constraints: ['Keep the null check before calling any String method.'],
    starter: program('System.out.println(isUtdEmail("Ana@UTDALLAS.EDU"));', { statics: 'static boolean isUtdEmail(String email) {\n    return email != null && email.endsWith("@utdallas.edu");\n}' }),
    reference: program('System.out.println(isUtdEmail("Ana@UTDALLAS.EDU"));', { statics: 'static boolean isUtdEmail(String email) {\n    return email != null && email.trim().toLowerCase().endsWith("@utdallas.edu");\n}' }),
    tests: checks('eq("uppercase", true, Main.isUtdEmail("Ana@UTDALLAS.EDU"));\neq("spaces", true, Main.isUtdEmail(" ben@utdallas.edu "));\neq("plain", true, Main.isUtdEmail("cam@utdallas.edu"));\neq("null", false, Main.isUtdEmail(null));\neq("gmail", false, Main.isUtdEmail("x@gmail.com"));\neq("domain first", false, Main.isUtdEmail("utdallas.edu@gmail.com"));'),
    hints: ['Normalize the text before calling endsWith.', 'Strings have trim() and toLowerCase(), and you can chain them.', 'return email != null && email.trim().toLowerCase().endsWith("@utdallas.edu");'],
  },
  practice: {
    title: 'Label the seats', signature: 'static String seatLabel(int seatsLeft)',
    prompt: 'Implement seatLabel to return a ride card label: Full for 0, 1 seat left for 1, N seats left for more, and Invalid for negative numbers.',
    description: 'Ride cards on the React frontend show a short seat label (see P2 question Q7).',
    requirements: ['Negative: "Invalid"', '0: "Full"', '1: "1 seat left" (singular)', '2 or more: "N seats left"'],
    examples: [['seatLabel(0)', '"Full"'], ['seatLabel(1)', '"1 seat left"'], ['seatLabel(3)', '"3 seats left"']],
    constraints: ['Return the label; do not print it.'],
    starter: program('System.out.println(seatLabel(3));', { statics: 'static String seatLabel(int seatsLeft) {\n    return "";\n}' }),
    reference: program('System.out.println(seatLabel(3));', { statics: 'static String seatLabel(int seatsLeft) {\n    if (seatsLeft < 0) return "Invalid";\n    if (seatsLeft == 0) return "Full";\n    if (seatsLeft == 1) return "1 seat left";\n    return seatsLeft + " seats left";\n}' }),
    tests: checks('eq("-1", "Invalid", Main.seatLabel(-1));\neq("0", "Full", Main.seatLabel(0));\neq("1", "1 seat left", Main.seatLabel(1));\neq("2", "2 seats left", Main.seatLabel(2));\neq("6", "6 seats left", Main.seatLabel(6));'),
    hints: ['Handle the special cases first, each with its own return.', 'Use == for ints; it is only Strings that need equals.', 'if (seatsLeft == 1) return "1 seat left"; ... return seatsLeft + " seats left";'],
  },
  sources: [{ title: 'dev.java: Strings', url: J + 'strings/' }],
}),

lesson({
  id: 'classes', title: 'Classes, objects & constructors', file: 'model/User.java',
  explanation: ['A class is a blueprint and new creates an object from it; the constructor sets the starting field values.', 'Variables of class type hold references, so two variables can point to the same object.'],
  overview: 'A class bundles data (fields) with behavior (methods). `new Ride("Ana", 3)` calls the constructor and returns a reference to a new object. In CometCarpool, User, LoginResponse, and later Ride are classes.',
  goals: ['Define a class with fields, a constructor, and methods.', 'Explain aliasing: why b.book() can change a.'],
  diagram: ['Objects and references', [['class Ride', 'Blueprint: fields driver, seats'], ['new Ride("Ana", 3)', 'Constructor builds one object'], ['Ride a = ...', 'a holds a reference (arrow) to it'], ['Ride b = a', 'Copies the arrow: same object']]],
  sections: [
    ['Fields and constructor', ['Fields are variables that belong to each object. The constructor has the class name and no return type.', '`this.seats = seats` means "the field" = "the parameter". this tells the two same-named things apart.'], 'class Ride {\n    String driver; int seats;\n    Ride(String driver, int seats) {\n        this.driver = driver; this.seats = seats;\n    }\n}'],
    ['Instance methods', ['A method without static runs on one object: r.book() changes r\'s seats.', 'Inside the method, a plain `seats` means this object\'s field.']],
    ['References and ==', ['Ride b = a; does not copy the ride. Both names point to one object.', '== on objects asks "same object?" Two rides with equal fields made by separate new calls are not ==.']],
    ['In CometCarpool', ['`public User() {}` is a no-argument constructor. JPA and Jackson need it to create a User before filling its fields.', '`new LoginResponse(token)` uses a one-argument constructor.']],
  ],
  misconception: 'Assigning one object variable to another does not clone it. Changes through either name affect the same object.',
  takeaway: 'Classes define shape and behavior; variables hold references to objects.',
  tryIt: 'Create a third Ride, book it twice, and print its seats.',
  example: program('Ride r = new Ride("Ana", 3);\nr.book();\nSystem.out.println(r.driver + " " + r.seats);\nRide other = new Ride("Ben", 2);\nSystem.out.println(other.seats);', { types: 'class Ride {\n    String driver;\n    int seats;\n\n    Ride(String driver, int seats) {\n        this.driver = driver;\n        this.seats = seats;\n    }\n\n    void book() {\n        seats = seats - 1;\n    }\n}' }),
  predict: { code: program('Ride a = new Ride("Ana", 3);\nRide b = a;\nb.book();\nRide c = new Ride("Ana", 3);\nSystem.out.println(a.seats + " " + b.seats + " " + c.seats);\nSystem.out.println((a == b) + " " + (a == c));', { types: 'class Ride {\n    String driver;\n    int seats;\n\n    Ride(String driver, int seats) {\n        this.driver = driver;\n        this.seats = seats;\n    }\n\n    void book() {\n        seats = seats - 1;\n    }\n}' }), expected: '2 2 3\ntrue false\n', explanation: 'a and b reference the same ride, so booking through b changes what a sees. c is a separate object with equal fields, so a == c is false.' },
  guided: {
    title: 'Never overbook', signature: 'boolean book()',
    prompt: 'Change book so it returns false and leaves seats unchanged when the ride is full, and otherwise takes one seat and returns true.',
    description: 'The starter book() always decrements, so seats can go negative and two riders can share one seat (P2 question Q12).',
    requirements: ['When seats is 0, return false and leave seats at 0.', 'Otherwise decrement seats and return true.'],
    examples: [['new Ride("Ana", 1).book() twice', 'true, then false; seats stays 0'], ['new Ride("Ben", 0).book()', 'false; seats stays 0']], constraints: ['Keep the constructor unchanged.'],
    starter: program('Ride r = new Ride("Ana", 1);\nSystem.out.println(r.book() + " " + r.book() + " " + r.seats);', { types: 'class Ride {\n    String driver;\n    int seats;\n\n    Ride(String driver, int seats) {\n        this.driver = driver;\n        this.seats = seats;\n    }\n\n    boolean book() {\n        seats = seats - 1;\n        return true;\n    }\n}' }),
    reference: program('Ride r = new Ride("Ana", 1);\nSystem.out.println(r.book() + " " + r.book() + " " + r.seats);', { types: 'class Ride {\n    String driver;\n    int seats;\n\n    Ride(String driver, int seats) {\n        this.driver = driver;\n        this.seats = seats;\n    }\n\n    boolean book() {\n        if (seats == 0) {\n            return false;\n        }\n        seats = seats - 1;\n        return true;\n    }\n}' }),
    tests: checks('Ride r = new Ride("Ana", 2);\neq("first booking", true, r.book());\neq("second booking", true, r.book());\neq("full ride", false, r.book());\neq("seats after full", 0, r.seats);\nRide z = new Ride("Ben", 0);\neq("empty ride", false, z.book());\neq("empty seats", 0, z.seats);'),
    hints: ['Check the current seats before changing anything.', 'An early return false stops the method before the decrement.', 'if (seats == 0) { return false; }'],
  },
  practice: {
    title: 'Does the request fit?', signature: 'RideRequest(String rider, int seatsWanted)\nboolean fits(Ride ride)',
    prompt: 'Complete RideRequest: store rider and seatsWanted in fields from the constructor, and make fits return whether a ride has enough seats left.',
    description: 'A rider asks for one or more seats (UC-03). Model the request as its own class.',
    requirements: ['Add fields rider (String) and seatsWanted (int), set by the constructor.', 'fits(ride) returns true when ride.seats >= seatsWanted.'],
    examples: [['new RideRequest("Cam", 2).fits(new Ride("Ana", 3))', 'true'], ['new RideRequest("Cam", 2).fits(new Ride("Ben", 1))', 'false'], ['new RideRequest("Dee", 2).fits(new Ride("Eve", 2))', 'true', 'Exactly enough seats fits.']],
    constraints: ['Do not change Ride.'],
    starter: program('System.out.println(new RideRequest("Cam", 2).fits(new Ride("Ana", 3)));', { types: 'class Ride {\n    String driver;\n    int seats;\n\n    Ride(String driver, int seats) {\n        this.driver = driver;\n        this.seats = seats;\n    }\n}\n\nclass RideRequest {\n    // Add fields here.\n\n    RideRequest(String rider, int seatsWanted) {\n    }\n\n    boolean fits(Ride ride) {\n        return false;\n    }\n}' }),
    reference: program('System.out.println(new RideRequest("Cam", 2).fits(new Ride("Ana", 3)));', { types: 'class Ride {\n    String driver;\n    int seats;\n\n    Ride(String driver, int seats) {\n        this.driver = driver;\n        this.seats = seats;\n    }\n}\n\nclass RideRequest {\n    String rider;\n    int seatsWanted;\n\n    RideRequest(String rider, int seatsWanted) {\n        this.rider = rider;\n        this.seatsWanted = seatsWanted;\n    }\n\n    boolean fits(Ride ride) {\n        return ride.seats >= seatsWanted;\n    }\n}' }),
    tests: checks('RideRequest r = new RideRequest("Cam", 2);\neq("rider field", "Cam", r.rider);\neq("seatsWanted field", 2, r.seatsWanted);\neq("3 seats", true, r.fits(new Ride("Ana", 3)));\neq("1 seat", false, r.fits(new Ride("Ben", 1)));\neq("exact", true, r.fits(new Ride("Eve", 2)));\neq("one seat request", true, new RideRequest("Fay", 1).fits(new Ride("Gus", 1)));'),
    hints: ['The fields need names and types that match the tests: rider and seatsWanted.', 'In the constructor, use this.rider = rider; to copy the parameter into the field.', 'return ride.seats >= seatsWanted;'],
  },
  sources: [{ title: 'dev.java: Classes and objects', url: J + 'classes-objects/' }],
}),

lesson({
  id: 'encapsulation', title: 'private fields, getters/setters & packages', file: 'model/User.java',
  explanation: ['private fields can only be touched inside their class; public getters and setters are the controlled doors.', 'package and import organize classes into folders such as com.cometcarpool.backend.model.'],
  overview: 'User.java has private fields with public getX/setX methods. Spring, JPA, and Jackson use those methods to read and fill objects. The `package` line at the top must match the folder the file lives in.',
  goals: ['Read and write getter/setter pairs like those in User.java.', 'Spot the classic setter bug where the field is never assigned.'],
  diagram: ['Who touches User\'s fields', [['private String email', 'Hidden inside User'], ['getEmail() / setEmail()', 'Public doors'], ['Jackson', 'Calls getters to write JSON'], ['JPA', 'Calls the no-arg constructor, then fills fields']]],
  sections: [
    ['Access modifiers', ['private: only code inside this class. public: any class. No modifier: same package only.', 'Hiding fields lets the class enforce rules, for example rejecting a negative seat count in setSeats.']],
    ['Getter/setter pattern', ['getX returns the field; setX(value) assigns it with this.x = x.', '@JsonIgnore on password keeps it out of JSON responses even though a getter exists.'], 'private String role;\npublic String getRole() { return role; }\npublic void setRole(String role) { this.role = role; }'],
    ['Packages and imports', ['`package com.cometcarpool.backend.model;` means the file sits in src/main/java/com/cometcarpool/backend/model/.', 'Another package must `import com.cometcarpool.backend.model.User;` to use it, as UserService does.']],
    ['In CometCarpool', ['User has six private fields and twelve accessor methods.', 'Known issue #13: Java records or Lombok can generate this boilerplate. You will meet records soon.']],
  ],
  misconception: 'In setName(String name) { name = name; }, the parameter is assigned to itself. Without this., the field is never set.',
  takeaway: 'Keep fields private, expose behavior through methods, and use this. when a parameter shares the field name.',
  tryIt: 'Remove this. from setEmail in the example and predict what prints.',
  example: program('User u = new User();\nSystem.out.println(u.getEmail());\nu.setEmail("ana@utdallas.edu");\nu.setPassword("hash");\nSystem.out.println(u.getEmail() + " " + u.hasPassword());', { types: 'class User {\n    private String email;\n    private String password;\n\n    public String getEmail() { return email; }\n    public void setEmail(String email) { this.email = email; }\n    public void setPassword(String password) { this.password = password; }\n    public boolean hasPassword() { return password != null; }\n}' }),
  predict: { code: program('Profile p = new Profile();\np.setName("Ana");\nSystem.out.println(p.getName());\nCounter c = new Counter();\nc.addRide();\nc.addRide();\nSystem.out.println(c.getRides());', { types: 'class Profile {\n    private String name;\n    public void setName(String name) { name = name; }\n    public String getName() { return name; }\n}\n\nclass Counter {\n    private int rides;\n    public void addRide() { rides++; }\n    public int getRides() { return rides; }\n}' }), expected: 'null\n2\n', explanation: 'setName assigns the parameter to itself, so the field stays null. Counter has no shadowing: rides++ updates the field twice, starting from 0.' },
  guided: {
    title: 'Fix setRole', signature: 'public void setRole(String role)',
    prompt: 'Change setRole so it actually stores the role in the field; right now getRole always returns null.',
    description: 'The starter User has the shadowing bug from Learn.',
    requirements: ['After setRole("DRIVER"), getRole() returns "DRIVER".', 'Calling setRole again replaces the value.'],
    examples: [['u.setRole("DRIVER"); u.getRole()', '"DRIVER"'], ['u.setRole("RIDER"); u.getRole()', '"RIDER"']], constraints: ['Keep the field private.'],
    starter: program('User u = new User();\nu.setRole("DRIVER");\nSystem.out.println(u.getRole());', { types: 'class User {\n    private String role;\n\n    public String getRole() { return role; }\n    public void setRole(String role) { role = role; }\n}' }),
    reference: program('User u = new User();\nu.setRole("DRIVER");\nSystem.out.println(u.getRole());', { types: 'class User {\n    private String role;\n\n    public String getRole() { return role; }\n    public void setRole(String role) { this.role = role; }\n}' }),
    tests: checks('User u = new User();\neq("before", null, u.getRole());\nu.setRole("DRIVER");\neq("after set", "DRIVER", u.getRole());\nu.setRole("RIDER");\neq("after reset", "RIDER", u.getRole());'),
    hints: ['Which role is the field and which is the parameter?', 'this.role refers to the field.', 'this.role = role;'],
  },
  practice: {
    title: 'Write a Vehicle class', signature: 'Vehicle(String make, int seats)\nString getMake()\nint getSeats()\nvoid setSeats(int seats)',
    prompt: 'Write Vehicle with private make and seats fields, a constructor, getters, and a setSeats that ignores values outside 1 to 7.',
    description: 'Drivers register a vehicle with a seat count. Encapsulation lets the class refuse impossible values.',
    requirements: ['Private fields make (String) and seats (int).', 'Constructor sets both.', 'getMake() and getSeats() return them.', 'setSeats(n) stores n only when 1 <= n <= 7; otherwise it keeps the old value.'],
    examples: [['new Vehicle("Civic", 4).getSeats()', '4'], ['v.setSeats(9); v.getSeats()', '4', 'Out of range: unchanged.'], ['v.setSeats(5); v.getSeats()', '5']],
    constraints: ['Assume the constructor gets a valid seat count.'],
    starter: program('Vehicle v = new Vehicle("Civic", 4);\nSystem.out.println(v.getMake() + " " + v.getSeats());', { types: 'class Vehicle {\n    // Write the fields, constructor, getters, and setSeats.\n\n    Vehicle(String make, int seats) {\n    }\n\n    public String getMake() { return null; }\n    public int getSeats() { return 0; }\n    public void setSeats(int seats) { }\n}' }),
    reference: program('Vehicle v = new Vehicle("Civic", 4);\nSystem.out.println(v.getMake() + " " + v.getSeats());', { types: 'class Vehicle {\n    private String make;\n    private int seats;\n\n    Vehicle(String make, int seats) {\n        this.make = make;\n        this.seats = seats;\n    }\n\n    public String getMake() { return make; }\n    public int getSeats() { return seats; }\n    public void setSeats(int seats) {\n        if (seats >= 1 && seats <= 7) {\n            this.seats = seats;\n        }\n    }\n}' }),
    tests: checks('Vehicle v = new Vehicle("Civic", 4);\neq("make", "Civic", v.getMake());\neq("seats", 4, v.getSeats());\nv.setSeats(9);\neq("ignore 9", 4, v.getSeats());\nv.setSeats(0);\neq("ignore 0", 4, v.getSeats());\nv.setSeats(5);\neq("accept 5", 5, v.getSeats());\nv.setSeats(7);\neq("accept 7", 7, v.getSeats());\nv.setSeats(1);\neq("accept 1", 1, v.getSeats());\nfor (var f : Vehicle.class.getDeclaredFields()) if (!java.lang.reflect.Modifier.isPrivate(f.getModifiers())) { failures++; System.err.println("field " + f.getName() + " should be private"); }'),
    hints: ['Start with the two private fields and the constructor, as in the guided fix.', 'setSeats should guard the assignment with an if.', 'if (seats >= 1 && seats <= 7) { this.seats = seats; }'],
  },
  sources: [{ title: 'dev.java: Controlling access', url: J + 'classes-objects/more-on-classes/' }],
}),

lesson({
  id: 'exceptions', title: 'Exceptions: throw, try & catch', file: 'service/UserService.java',
  explanation: ['throw stops the current method and travels up the call stack until a matching catch handles it.', 'CometCarpool signals bad input with IllegalArgumentException, and GlobalExceptionHandler turns it into HTTP 400.'],
  overview: 'When saveUser sees a non-UTD email it calls `throw new IllegalArgumentException("User must be a student...")`. Nothing after the throw runs. The exception climbs out of the service and the controller, where Spring\'s handler catches it and replies 400.',
  goals: ['Throw an exception with a helpful message and catch it at the right level.', 'Trace try/catch/finally order and recognize exception subclasses.'],
  diagram: ['An exception\'s journey', [['UserService.saveUser', 'throw new IllegalArgumentException(...)'], ['UserController.createUser', 'No catch here, so it keeps rising'], ['GlobalExceptionHandler', '@ExceptionHandler catches it'], ['HTTP response', '400 Bad Request with the message']]],
  sections: [
    ['throw', ['`throw new IllegalArgumentException("message")` creates an exception object and abandons the method.', 'getMessage() returns the text you passed in. Write it for the person who will read the 400 response.']],
    ['try / catch / finally', ['Code that might throw goes in try. A matching catch block runs instead of crashing.', 'finally runs whether or not an exception happened, even when try returns. Use it for cleanup.'], 'try {\n    service.saveUser(u);\n} catch (IllegalArgumentException e) {\n    System.out.println("400: " + e.getMessage());\n}'],
    ['The exception family', ['NumberFormatException is a kind of IllegalArgumentException, so catch (IllegalArgumentException e) also catches bad Integer.parseInt input.', 'Checked exceptions (like IOException) must be declared with throws. Unchecked ones (RuntimeException subclasses) need not be. Spring code mostly uses unchecked exceptions.']],
    ['In CometCarpool', ['loginUser throws the same "Invalid email or password" for an unknown email and for a wrong password, so attackers can\'t learn which emails exist.', 'GlobalExceptionHandler has @ExceptionHandler(IllegalArgumentException.class), so every such throw becomes a 400 response.']],
  ],
  misconception: 'catch does not resume the code after the throw. Execution continues after the whole try/catch statement.',
  takeaway: 'Throw where you detect the problem; catch where you know how to respond.',
  tryIt: 'Add tryParse("-2") to the example. Which message prints?',
  example: program('tryParse("3");\ntryParse("0");\ntryParse("abc");', { statics: 'static int parseSeats(String raw) {\n    int seats = Integer.parseInt(raw);\n    if (seats < 1) {\n        throw new IllegalArgumentException("Seats must be at least 1");\n    }\n    return seats;\n}\n\nstatic void tryParse(String raw) {\n    try {\n        System.out.println("ok " + parseSeats(raw));\n    } catch (IllegalArgumentException e) {\n        System.out.println("error: " + e.getMessage());\n    }\n}' }),
  predict: { code: program('System.out.println(login("ana"));\nSystem.out.println(login(null));', { statics: 'static String login(String email) {\n    try {\n        if (email == null) {\n            throw new IllegalArgumentException("Invalid email or password");\n        }\n        return "token-for-" + email;\n    } catch (IllegalArgumentException e) {\n        return "401 " + e.getMessage();\n    } finally {\n        System.out.println("login attempt");\n    }\n}' }), expected: 'login attempt\ntoken-for-ana\nlogin attempt\n401 Invalid email or password\n', explanation: 'finally runs before the method actually returns, so "login attempt" prints before the caller prints the returned value. With null, catch builds the 401 string, finally prints, and then the caller prints.' },
  guided: {
    title: 'Throw on non-UTD emails', signature: 'static void requireUtdEmail(String email)',
    prompt: 'Change requireUtdEmail so it throws IllegalArgumentException with the exact CometCarpool message when the email is null or not a UTD address.',
    description: 'The starter does nothing, so every email passes.',
    requirements: ['null or not ending in @utdallas.edu: throw new IllegalArgumentException("User must be a student with a UTD email address.")', 'Valid UTD email: return normally.'],
    examples: [['requireUtdEmail("ana@utdallas.edu")', 'returns normally'], ['requireUtdEmail("ana@gmail.com")', 'throws IllegalArgumentException']],
    constraints: ['Use the exact message text.'],
    starter: program('requireUtdEmail("ana@gmail.com");\nSystem.out.println("passed");', { statics: 'static void requireUtdEmail(String email) {\n    // Throw when the email is missing or not a UTD address.\n}' }),
    reference: program('requireUtdEmail("ana@utdallas.edu");\nSystem.out.println("passed");', { statics: 'static void requireUtdEmail(String email) {\n    if (email == null || !email.endsWith("@utdallas.edu")) {\n        throw new IllegalArgumentException("User must be a student with a UTD email address.");\n    }\n}' }),
    tests: checks('String msg = "User must be a student with a UTD email address.";\nexpectThrows("gmail", IllegalArgumentException.class, msg, () -> Main.requireUtdEmail("ana@gmail.com"));\nexpectThrows("null", IllegalArgumentException.class, msg, () -> Main.requireUtdEmail(null));\nMain.requireUtdEmail("ana@utdallas.edu");'),
    hints: ['Reuse the condition from the conditions lesson.', 'throw new IllegalArgumentException("...") inside the if.', 'if (email == null || !email.endsWith("@utdallas.edu")) { throw new IllegalArgumentException("User must be a student with a UTD email address."); }'],
  },
  practice: {
    title: 'Map validation to a status', signature: 'static void validatePassword(String password)\nstatic String register(String email, String password)',
    prompt: 'Implement validatePassword to throw for short or missing passwords, and register to call it and turn any IllegalArgumentException into a "400: message" result instead of crashing.',
    description: 'This mimics how GlobalExceptionHandler converts exceptions into 400 responses. It is also the fix for known issue #7 (a null password crashes with 500).',
    requirements: ['validatePassword: null or shorter than 8 characters throws IllegalArgumentException("Password must be at least 8 characters").', 'register: if validatePassword throws, return "400: " + message; otherwise return "201: " + email.'],
    examples: [['register("ana@utdallas.edu", "longenough")', '"201: ana@utdallas.edu"'], ['register("ana@utdallas.edu", "short")', '"400: Password must be at least 8 characters"'], ['register("ana@utdallas.edu", null)', '"400: Password must be at least 8 characters"']],
    constraints: ['register must not let the exception escape.'],
    starter: program('System.out.println(register("ana@utdallas.edu", "short"));', { statics: 'static void validatePassword(String password) {\n}\n\nstatic String register(String email, String password) {\n    return "";\n}' }),
    reference: program('System.out.println(register("ana@utdallas.edu", "short"));', { statics: 'static void validatePassword(String password) {\n    if (password == null || password.length() < 8) {\n        throw new IllegalArgumentException("Password must be at least 8 characters");\n    }\n}\n\nstatic String register(String email, String password) {\n    try {\n        validatePassword(password);\n        return "201: " + email;\n    } catch (IllegalArgumentException e) {\n        return "400: " + e.getMessage();\n    }\n}' }),
    tests: checks('String m = "Password must be at least 8 characters";\nexpectThrows("validate short", IllegalArgumentException.class, m, () -> Main.validatePassword("abc"));\nexpectThrows("validate null", IllegalArgumentException.class, m, () -> Main.validatePassword(null));\nMain.validatePassword("12345678");\neq("ok", "201: ana@utdallas.edu", Main.register("ana@utdallas.edu", "longenough"));\neq("short", "400: " + m, Main.register("ana@utdallas.edu", "short"));\neq("null", "400: " + m, Main.register("ben@utdallas.edu", null));\neq("exactly 8", "201: cam@utdallas.edu", Main.register("cam@utdallas.edu", "12345678"));'),
    hints: ['Check for null before calling length().', 'register puts the risky call inside try and builds the 400 string in catch.', 'try { validatePassword(password); return "201: " + email; } catch (IllegalArgumentException e) { return "400: " + e.getMessage(); }'],
  },
  sources: [{ title: 'dev.java: Exceptions', url: J + 'exceptions/' }],
}),

lesson({
  id: 'collections', title: 'Lists, Maps & generics', file: 'service/UserService.java',
  explanation: ['List<T> is an ordered collection; Map<K, V> looks values up by key. The <...> part is a generic type parameter.', 'getAllUsers returns List<User>, and JpaRepository<User, Long> means a repository of Users keyed by Long ids.'],
  overview: 'Generics let one collection class hold a specific type safely: `List<String>` only holds Strings. CometCarpool returns `List<User>` from getAllUsers, and `JpaRepository<User, Long>` reads as "store Users whose id type is Long".',
  goals: ['Use ArrayList and HashMap: add, get, put, getOrDefault, and for-each.', 'Read generic types like Map<String, List<String>>.'],
  diagram: ['Two workhorse collections', [['List<String>', 'Index 0, 1, 2 in insertion order; duplicates allowed'], ['Map<String, Integer>', 'Key to value; putting the same key replaces'], ['Missing key', 'map.get returns null'], ['for (T x : list)', 'Visits each element in order']]],
  sections: [
    ['Lists', ['`List<String> riders = new ArrayList<>();` creates an empty, growable list. add appends; get(i) reads by index; size() counts.', 'List.of(...) makes a fixed list you cannot add to. Wrap it in new ArrayList<>(...) to get a mutable copy.']],
    ['Maps', ['put(key, value) inserts or replaces. get(key) returns null when the key is missing; getOrDefault(key, fallback) avoids that.', 'containsKey(key) asks whether the key exists.'], 'Map<String, Integer> seats = new HashMap<>();\nseats.put("ride-1", 3);\nseats.getOrDefault("ride-2", 0); // 0'],
    ['Reading generics', ['The <> holds type arguments. Map<String, List<String>> maps ride ids to lists of rider names.', 'Primitives cannot be type arguments, so you write List<Integer>, not List<int>. Java boxes and unboxes for you.']],
    ['In CometCarpool', ['`userRepository.findAll()` returns `List<User>`, and the controller returns it straight as a JSON array.', 'Bookings per ride will naturally be a Map<Long, List<RideRequest>>, or a query.']],
  ],
  misconception: 'list.remove(1) on a List<Integer> removes index 1, not the value 1. Use remove(Integer.valueOf(1)) to remove by value.',
  takeaway: 'List for ordered items, Map for lookup by key; the generic types document exactly what each one holds.',
  tryIt: 'Put "ride-2" into seats and predict both prints again.',
  example: program('List<String> riders = new ArrayList<>();\nriders.add("Ana");\nriders.add("Ben");\nriders.add("Ana");\nMap<String, Integer> seats = new HashMap<>();\nseats.put("ride-1", 3);\nseats.put("ride-1", 2);\nSystem.out.println(riders.size() + " " + riders.get(1));\nSystem.out.println(seats.get("ride-1") + " " + seats.get("ride-2"));\nfor (String r : riders) {\n    System.out.print(r + ";");\n}\nSystem.out.println();'),
  predict: { code: program('List<Integer> seats = new ArrayList<>(List.of(3, 1, 4));\nseats.remove(Integer.valueOf(1));\nseats.add(0, 2);\nMap<String, List<String>> byRide = new HashMap<>();\nbyRide.put("r1", new ArrayList<>());\nbyRide.get("r1").add("Ana");\nbyRide.get("r1").add("Ben");\nSystem.out.println(seats);\nSystem.out.println(byRide.get("r1").size() + " " + byRide.containsKey("r2"));'), expected: '[2, 3, 4]\n2 false\n', explanation: 'Removing the value 1 leaves [3, 4]; add(0, 2) inserts at the front. The map holds one list with two riders, and r2 was never put.' },
  guided: {
    title: 'No null rider lists', signature: 'static List<String> ridersFor(Map<String, List<String>> bookings, String rideId)',
    prompt: 'Change ridersFor so a ride with no bookings returns an empty list instead of null.',
    description: 'The starter returns bookings.get(rideId), which is null for unknown rides. The frontend would then crash calling .length on it.',
    requirements: ['Return the stored list when the ride exists.', 'Return an empty list when it does not.'],
    examples: [['ridersFor({r1=[Ana]}, "r1")', '[Ana]'], ['ridersFor({r1=[Ana]}, "r9")', '[]']], constraints: ['Do not modify the map.'],
    starter: program('System.out.println(ridersFor(new HashMap<>(), "r9"));', { statics: 'static List<String> ridersFor(Map<String, List<String>> bookings, String rideId) {\n    return bookings.get(rideId);\n}' }),
    reference: program('System.out.println(ridersFor(new HashMap<>(), "r9"));', { statics: 'static List<String> ridersFor(Map<String, List<String>> bookings, String rideId) {\n    return bookings.getOrDefault(rideId, new ArrayList<>());\n}' }),
    tests: checks('Map<String, List<String>> b = new HashMap<>();\nb.put("r1", new ArrayList<>(List.of("Ana", "Ben")));\neq("existing", List.of("Ana", "Ben"), Main.ridersFor(b, "r1"));\nList<String> none = Main.ridersFor(b, "r9");\neq("missing is empty list", List.of(), none);\neq("map unchanged", 1, b.size());'),
    hints: ['There is a Map method that takes a fallback value.', 'Pass an empty list as the fallback.', 'return bookings.getOrDefault(rideId, new ArrayList<>());'],
  },
  practice: {
    title: 'Seats by driver', signature: 'static Map<String, Integer> seatsByDriver(List<String> drivers, List<Integer> seats)',
    prompt: 'Implement seatsByDriver to add up the offered seats per driver, where drivers.get(i) offered seats.get(i).',
    description: 'A driver can post several rides. Sum each driver\'s offered seats for a dashboard.',
    requirements: ['drivers and seats have the same length; index i belongs together.', 'Return a map from driver name to the total seats.', 'Empty input returns an empty map.'],
    examples: [['(["Ana","Ben","Ana"], [3,2,1])', '{Ana=4, Ben=2}'], ['([], [])', '{}'], ['(["Cam"], [0])', '{Cam=0}', 'Zero-seat rides still appear.']],
    constraints: ['Do not mutate the input lists.'],
    starter: program('System.out.println(seatsByDriver(List.of("Ana", "Ben", "Ana"), List.of(3, 2, 1)));', { statics: 'static Map<String, Integer> seatsByDriver(List<String> drivers, List<Integer> seats) {\n    return new HashMap<>();\n}' }),
    reference: program('System.out.println(seatsByDriver(List.of("Ana", "Ben", "Ana"), List.of(3, 2, 1)));', { statics: 'static Map<String, Integer> seatsByDriver(List<String> drivers, List<Integer> seats) {\n    Map<String, Integer> totals = new HashMap<>();\n    for (int i = 0; i < drivers.size(); i++) {\n        String d = drivers.get(i);\n        totals.put(d, totals.getOrDefault(d, 0) + seats.get(i));\n    }\n    return totals;\n}' }),
    tests: checks('eq("mixed", Map.of("Ana", 4, "Ben", 2), Main.seatsByDriver(List.of("Ana", "Ben", "Ana"), List.of(3, 2, 1)));\neq("empty", Map.of(), Main.seatsByDriver(List.of(), List.of()));\neq("zero", Map.of("Cam", 0), Main.seatsByDriver(List.of("Cam"), List.of(0)));\neq("one driver", Map.of("Dee", 6), Main.seatsByDriver(List.of("Dee", "Dee", "Dee"), List.of(1, 2, 3)));'),
    hints: ['Loop over indexes with for (int i = 0; i < drivers.size(); i++).', 'Read the current total with getOrDefault(driver, 0), then put the new sum.', 'totals.put(d, totals.getOrDefault(d, 0) + seats.get(i));'],
  },
  sources: [{ title: 'dev.java: The Collections Framework', url: J + 'api/collections-framework/' }],
}),

lesson({
  id: 'interfaces', title: 'Interfaces & polymorphism', file: 'repository/UserRepository.java',
  explanation: ['An interface lists method signatures without bodies; any class can implement it.', 'Code written against an interface (PasswordEncoder, UserRepository) works with any implementation: a real one in production, a fake one in tests.'],
  overview: 'UserService never says which hashing algorithm or database it uses. It holds a `PasswordEncoder` and a `UserRepository`, both interfaces. Spring plugs in BCrypt and a Postgres-backed repository; your tests can plug in fakes.',
  goals: ['Define an interface and implement it in two classes.', 'Call methods through an interface type and predict which implementation runs.'],
  diagram: ['Programming to an interface', [['interface PasswordEncoder', 'encode(raw), matches(raw, encoded)'], ['BCryptPasswordEncoder', 'Real implementation (Spring)'], ['FakeEncoder', 'Test implementation (yours)'], ['UserService', 'Only knows the interface']]],
  sections: [
    ['Declaring and implementing', ['An interface method has no body. `class X implements PasswordEncoder` must provide every method, as public.', 'A class can implement several interfaces.'], 'interface PasswordEncoder {\n    String encode(String raw);\n    boolean matches(String raw, String encoded);\n}'],
    ['Polymorphism', ['A variable of interface type can hold any implementing object: `PasswordEncoder e = new BCryptPasswordEncoder();`.', 'The method that runs is chosen by the actual object at runtime, not by the variable\'s type.']],
    ['Why services take interfaces', ['Swapping implementations needs no change to the caller. That is what lets Spring inject real beans and tests inject fakes.', '`instanceof` checks the runtime class, but needing it often means the interface is missing a method.']],
    ['In CometCarpool', ['`interface UserRepository extends JpaRepository<User, Long>`: you declare methods and Spring writes the class at startup.', 'PasswordEncoder is a Spring Security interface; SecurityConfig chooses BCrypt.']],
  ],
  misconception: 'You cannot write new PasswordEncoder(). An interface has no implementation, so you create an object of a class that implements it.',
  takeaway: 'Depend on interfaces; choose implementations at the edges (Spring config or tests).',
  tryIt: 'Add a third encoder that uppercases the password and pass it to register.',
  example: program('System.out.println(register(new ReverseEncoder(), "abc123"));\nPasswordEncoder e = new PlainEncoder();\nSystem.out.println(register(e, "abc123") + " " + e.matches("abc123", "abc123"));', { types: 'interface PasswordEncoder {\n    String encode(String raw);\n    boolean matches(String raw, String encoded);\n}\n\nclass ReverseEncoder implements PasswordEncoder {\n    public String encode(String raw) { return new StringBuilder(raw).reverse().toString(); }\n    public boolean matches(String raw, String encoded) { return encode(raw).equals(encoded); }\n}\n\nclass PlainEncoder implements PasswordEncoder {\n    public String encode(String raw) { return raw; }\n    public boolean matches(String raw, String encoded) { return raw.equals(encoded); }\n}', statics: 'static String register(PasswordEncoder encoder, String raw) {\n    return encoder.encode(raw);\n}' }),
  predict: { code: program('List<Notifier> ns = List.of(new SmsNotifier(), new EmailNotifier());\nfor (Notifier n : ns) {\n    System.out.println(n.send("ana"));\n}\nNotifier n = ns.get(1);\nSystem.out.println(n instanceof EmailNotifier);', { types: 'interface Notifier {\n    String send(String to);\n}\n\nclass EmailNotifier implements Notifier {\n    public String send(String to) { return "email:" + to; }\n}\n\nclass SmsNotifier implements Notifier {\n    public String send(String to) { return "sms:" + to; }\n}' }), expected: 'sms:ana\nemail:ana\ntrue\n', explanation: 'Each element runs its own send. The list order is SMS, then email. Index 1 holds the EmailNotifier object.' },
  guided: {
    title: 'Make the in-memory store remember', signature: 'class MemoryUserStore implements UserStore',
    prompt: 'Change MemoryUserStore so save remembers emails and existsByEmail reports whether an email was saved.',
    description: 'The starter save forgets everything and existsByEmail always returns false, so duplicate sign-ups slip through.',
    requirements: ['save(email) records the email.', 'existsByEmail(email) returns true only for saved emails.'],
    examples: [['save("ana@utdallas.edu"); existsByEmail("ana@utdallas.edu")', 'true'], ['existsByEmail("ben@utdallas.edu")', 'false']], constraints: ['Keep implementing UserStore.'],
    starter: program('UserStore s = new MemoryUserStore();\ns.save("ana@utdallas.edu");\nSystem.out.println(s.existsByEmail("ana@utdallas.edu"));', { types: 'interface UserStore {\n    boolean existsByEmail(String email);\n    void save(String email);\n}\n\nclass MemoryUserStore implements UserStore {\n    public boolean existsByEmail(String email) { return false; }\n    public void save(String email) { }\n}' }),
    reference: program('UserStore s = new MemoryUserStore();\ns.save("ana@utdallas.edu");\nSystem.out.println(s.existsByEmail("ana@utdallas.edu"));', { types: 'interface UserStore {\n    boolean existsByEmail(String email);\n    void save(String email);\n}\n\nclass MemoryUserStore implements UserStore {\n    private final List<String> emails = new ArrayList<>();\n    public boolean existsByEmail(String email) { return emails.contains(email); }\n    public void save(String email) { emails.add(email); }\n}' }),
    tests: checks('UserStore s = new MemoryUserStore();\neq("empty", false, s.existsByEmail("ana@utdallas.edu"));\ns.save("ana@utdallas.edu");\neq("saved", true, s.existsByEmail("ana@utdallas.edu"));\neq("other", false, s.existsByEmail("ben@utdallas.edu"));\nUserStore t = new MemoryUserStore();\neq("separate stores", false, t.existsByEmail("ana@utdallas.edu"));'),
    hints: ['The store needs a field to hold emails.', 'A List<String> field with add and contains is enough.', 'private final List<String> emails = new ArrayList<>(); ... return emails.contains(email);'],
  },
  practice: {
    title: 'Sign up against any store', signature: 'static String signUp(UserStore store, String email)',
    prompt: 'Implement signUp using only the UserStore interface: return duplicate for existing emails, and otherwise save the email and return saved.',
    description: 'The tests pass in their own fake UserStore. Your code must work with any implementation.',
    requirements: ['If store.existsByEmail(email): return "duplicate" and do not save.', 'Otherwise call store.save(email) once and return "saved".'],
    examples: [['signUp(storeWith("ana@utdallas.edu"), "ana@utdallas.edu")', '"duplicate"'], ['signUp(emptyStore, "ben@utdallas.edu")', '"saved"', 'save is called exactly once.']],
    constraints: ['Use only the interface methods.'],
    starter: program('System.out.println("see tests");', { types: 'interface UserStore {\n    boolean existsByEmail(String email);\n    void save(String email);\n}', statics: 'static String signUp(UserStore store, String email) {\n    return "";\n}' }),
    reference: program('System.out.println("see tests");', { types: 'interface UserStore {\n    boolean existsByEmail(String email);\n    void save(String email);\n}', statics: 'static String signUp(UserStore store, String email) {\n    if (store.existsByEmail(email)) {\n        return "duplicate";\n    }\n    store.save(email);\n    return "saved";\n}' }),
    tests: checks('FakeStore f = new FakeStore();\nf.existing.add("ana@utdallas.edu");\neq("duplicate", "duplicate", Main.signUp(f, "ana@utdallas.edu"));\neq("no save on duplicate", 0, f.saves.size());\neq("new", "saved", Main.signUp(f, "ben@utdallas.edu"));\neq("saved once", List.of("ben@utdallas.edu"), f.saves);', { types: 'class FakeStore implements UserStore {\n    List<String> existing = new ArrayList<>();\n    List<String> saves = new ArrayList<>();\n    public boolean existsByEmail(String email) { return existing.contains(email); }\n    public void save(String email) { saves.add(email); }\n}' }),
    hints: ['You only have two methods: existsByEmail and save.', 'Check first, then save. Return early on a duplicate.', 'if (store.existsByEmail(email)) return "duplicate"; store.save(email); return "saved";'],
  },
  sources: [{ title: 'dev.java: Interfaces', url: J + 'interfaces/' }],
}),

lesson({
  id: 'optional', title: 'null, NullPointerException & Optional', file: 'service/UserService.java',
  explanation: ['Calling a method on null throws NullPointerException; check for null or use Optional to make absence explicit.', 'findByEmail returns null for a missing user, but JpaRepository.findById returns Optional<User>.'],
  overview: '`userRepository.findByEmail(email)` returns null when no user exists, so loginUser must check for null before using the result. `Optional<User>` is the safer contract: the type itself says "might be empty".',
  goals: ['Prevent NullPointerExceptions with checks in the right order.', 'Create and unwrap Optionals with ofNullable, isPresent, and orElse.'],
  diagram: ['Two ways to say "not found"', [['null', 'Easy to forget; crashes when used'], ['Optional.empty()', 'Type forces the caller to decide'], ['orElse(x)', 'Use a fallback value'], ['orElseThrow()', 'Turn absence into an exception (404)']]],
  sections: [
    ['Where NPEs come from', ['`user.getEmail()` throws when user is null. The stack trace points at the line, not at where the null came from.', 'Calling equals on the known non-null side, as in `"x".equals(maybeNull)`, is safe. Objects.equals(a, b) handles null on both sides.']],
    ['Optional basics', ['Optional.of(x) requires non-null x. Optional.ofNullable(x) wraps a value that might be null. Optional.empty() is an empty box.', 'isPresent(), get(), orElse(fallback), orElseThrow(), and map(f) unwrap or transform it.'], 'Optional<User> u = repo.findById(id);\nUser user = u.orElseThrow(() -> new NotFoundException("No user " + id));'],
    ['Design rule', ['Return Optional from lookups that can miss. Don\'t store Optional in fields or accept it as a parameter.', 'Spring Data lets you declare `Optional<User> findByEmail(String email)` instead of returning a nullable User.']],
    ['In CometCarpool', ['loginUser checks `if (user == null)` before calling matches. Swapping the two checks would turn a wrong email into a 500 crash instead of a clean 400.', 'A future GET /api/rides/{id} would use findById(id).orElseThrow(...) to produce a 404.']],
  ],
  misconception: 'Optional.of(null) does not produce an empty Optional; it throws NullPointerException. Use ofNullable for values that may be null.',
  takeaway: 'Absence is normal for lookups. Model it with Optional, or check for null before you dereference.',
  tryIt: 'Change the example to call findEmail(users, 1L).isPresent() and predict it.',
  example: program('Map<Long, String> users = new HashMap<>();\nusers.put(1L, "ana@utdallas.edu");\nSystem.out.println(findEmail(users, 1L).orElse("missing"));\nSystem.out.println(findEmail(users, 2L).orElse("missing"));\nSystem.out.println(findEmail(users, 2L).isPresent());', { statics: 'static Optional<String> findEmail(Map<Long, String> users, Long id) {\n    return Optional.ofNullable(users.get(id));\n}' }),
  predict: { code: program('String email = null;\nSystem.out.println("x".equals(email));\nSystem.out.println(Objects.equals(email, null));\nOptional<String> o = Optional.of("ben@utdallas.edu");\nSystem.out.println(o.isPresent() && o.get().startsWith("ben"));\nOptional<String> empty = Optional.empty();\nSystem.out.println(empty.orElse("guest"));'), expected: 'false\ntrue\ntrue\nguest\n', explanation: '"x".equals(null) is false, with no crash. Objects.equals treats two nulls as equal. The Optional holds a value starting with ben. An empty Optional falls back to guest.' },
  guided: {
    title: 'Null-safe login', signature: 'static String loginMessage(Map<String, String> passwordsByEmail, String email, String password)',
    prompt: 'Change loginMessage so an unknown email returns "Invalid email or password" instead of throwing NullPointerException.',
    description: 'The starter calls .equals on the map lookup, which is null for unknown emails.',
    requirements: ['Unknown email: "Invalid email or password".', 'Wrong password: "Invalid email or password".', 'Correct password: "ok".'],
    examples: [['known email, right password', '"ok"'], ['unknown email', '"Invalid email or password"'], ['known email, wrong password', '"Invalid email or password"']],
    constraints: ['Use the same message for both failures, as UserService does.'],
    starter: program('System.out.println(loginMessage(new HashMap<>(), "x@utdallas.edu", "pw"));', { statics: 'static String loginMessage(Map<String, String> passwordsByEmail, String email, String password) {\n    if (passwordsByEmail.get(email).equals(password)) {\n        return "ok";\n    }\n    return "Invalid email or password";\n}' }),
    reference: program('System.out.println(loginMessage(new HashMap<>(), "x@utdallas.edu", "pw"));', { statics: 'static String loginMessage(Map<String, String> passwordsByEmail, String email, String password) {\n    String stored = passwordsByEmail.get(email);\n    if (stored != null && stored.equals(password)) {\n        return "ok";\n    }\n    return "Invalid email or password";\n}' }),
    tests: checks('Map<String, String> db = new HashMap<>(Map.of("ana@utdallas.edu", "secret123"));\neq("ok", "ok", Main.loginMessage(db, "ana@utdallas.edu", "secret123"));\neq("unknown", "Invalid email or password", Main.loginMessage(db, "zed@utdallas.edu", "secret123"));\neq("wrong", "Invalid email or password", Main.loginMessage(db, "ana@utdallas.edu", "nope"));\neq("null password", "Invalid email or password", Main.loginMessage(db, "ana@utdallas.edu", null));'),
    hints: ['Store the lookup result in a variable first.', 'Check it for null before calling equals on it.', 'String stored = passwordsByEmail.get(email); if (stored != null && stored.equals(password)) return "ok";'],
  },
  practice: {
    title: 'Who is driving?', signature: 'static Optional<String> driverFor(Map<String, String> driverByRide, String rideId)\nstatic String describe(Optional<String> driver)',
    prompt: 'Implement driverFor to return an Optional that is empty for unknown rides or blank driver names, and describe to turn it into a display string.',
    description: 'Ride cards show "Driver: Ana", or "No driver yet" when no one is assigned.',
    requirements: ['driverFor: empty when rideId is missing or its driver is blank; otherwise Optional.of(driver).', 'describe: "Driver: " + name when present, "No driver yet" when empty.'],
    examples: [['driverFor({r1=Ana}, "r1")', 'Optional[Ana]'], ['driverFor({r1=" "}, "r1")', 'Optional.empty', 'Blank counts as missing.'], ['describe(Optional.empty())', '"No driver yet"']],
    constraints: ['Never return null from driverFor.'],
    starter: program('System.out.println(describe(driverFor(Map.of("r1", "Ana"), "r1")));', { statics: 'static Optional<String> driverFor(Map<String, String> driverByRide, String rideId) {\n    return Optional.empty();\n}\n\nstatic String describe(Optional<String> driver) {\n    return "";\n}' }),
    reference: program('System.out.println(describe(driverFor(Map.of("r1", "Ana"), "r1")));', { statics: 'static Optional<String> driverFor(Map<String, String> driverByRide, String rideId) {\n    String d = driverByRide.get(rideId);\n    if (d == null || d.isBlank()) {\n        return Optional.empty();\n    }\n    return Optional.of(d);\n}\n\nstatic String describe(Optional<String> driver) {\n    if (driver.isPresent()) {\n        return "Driver: " + driver.get();\n    }\n    return "No driver yet";\n}' }),
    tests: checks('Map<String, String> m = new HashMap<>();\nm.put("r1", "Ana");\nm.put("r2", "  ");\neq("known", Optional.of("Ana"), Main.driverFor(m, "r1"));\neq("blank", Optional.empty(), Main.driverFor(m, "r2"));\neq("unknown", Optional.empty(), Main.driverFor(m, "r9"));\neq("describe present", "Driver: Ana", Main.describe(Optional.of("Ana")));\neq("describe empty", "No driver yet", Main.describe(Optional.empty()));'),
    hints: ['Look up the value, then decide which Optional to build.', 'isBlank() is true for "" and for all-space strings.', 'return driver.isPresent() ? "Driver: " + driver.get() : "No driver yet";'],
  },
  sources: [{ title: 'dev.java: Using Optionals', url: J + 'api/streams/optionals/' }],
}),

lesson({
  id: 'records-enums', title: 'Records, enums & DTOs', file: 'dto/LoginRequest.java',
  explanation: ['A record is a compact immutable data class: Java writes the constructor, accessors, equals, and toString for you.', 'An enum is a fixed set of named constants, which is safer than free-text Strings like User.role.'],
  overview: 'LoginRequest and LoginResponse are DTOs (data transfer objects): the shape of JSON going in and out. As records, they shrink from 25 lines to one. Making role an enum blocks "role": "superadmin" (known issue #4).',
  goals: ['Declare records and enums and use their generated methods.', 'Explain why a response DTO, not the User entity, should be what the API returns.'],
  diagram: ['Entity vs DTO', [['RegisterRequest (record)', 'Only the fields a client may send'], ['User (entity)', 'Full DB row, including the password hash'], ['UserResponse (record)', 'Only the fields safe to return'], ['Role (enum)', 'RIDER, DRIVER, ADMIN; nothing else compiles']]],
  sections: [
    ['Records', ['`record LoginRequest(String email, String password) {}` gives a constructor, accessors email() and password(), plus equals, hashCode, and toString.', 'Records are immutable, so there are no setters. Spring and Jackson bind JSON to records directly.'], 'public record LoginResponse(String token) {}'],
    ['Enums', ['`enum Role { RIDER, DRIVER, ADMIN }` defines exactly three values. Compare them with ==.', 'Role.valueOf("DRIVER") parses text and throws IllegalArgumentException for unknown names. values() lists them all. Switch expressions work well with enums.']],
    ['Why DTOs', ['UserController.createUser binds the whole User entity from the request, so a client can send "id" or "role": "ADMIN" (known issue #4).', 'A RegisterRequest record without role, plus server-side role assignment, closes that hole.']],
    ['In CometCarpool', ['LoginRequest, LoginResponse, and a future RideResponse are natural records.', 'JPA entities like User stay regular classes, because JPA needs a no-arg constructor and mutable fields.']],
  ],
  misconception: 'Two records with the same field values are equals but not ==. Records compare by value in equals; == still means the same object.',
  takeaway: 'Use records for data in motion (DTOs), enums for fixed choices, and classes for entities.',
  tryIt: 'Print Role.values().length and Role.ADMIN.name().',
  example: program('RegisterRequest req = new RegisterRequest("ana@utdallas.edu", "secret123", "Ana");\nUserResponse res = new UserResponse(1L, req.email(), Role.RIDER);\nSystem.out.println(res);\nSystem.out.println(res.role() == Role.RIDER);\nSystem.out.println(Role.valueOf("DRIVER").ordinal());', { types: 'enum Role { RIDER, DRIVER, ADMIN }\n\nrecord RegisterRequest(String email, String password, String firstName) {}\n\nrecord UserResponse(Long id, String email, Role role) {}' }),
  predict: { code: program('Seat a = new Seat("r1", 2);\nSeat b = new Seat("r1", 2);\nSystem.out.println(a.equals(b) + " " + (a == b));\nSystem.out.println(label(Status.FULL));\nSystem.out.println(Status.values().length);', { types: 'record Seat(String rideId, int number) {}\n\nenum Status { OPEN, FULL, CANCELLED }', statics: 'static String label(Status s) {\n    return switch (s) {\n        case OPEN -> "Book now";\n        case FULL -> "Waitlist";\n        case CANCELLED -> "Gone";\n    };\n}' }), expected: 'true false\nWaitlist\n3\n', explanation: 'Records get value-based equals, but == compares identity. The switch maps FULL to Waitlist. Status declares three constants.' },
  guided: {
    title: 'Stop leaking the password', signature: 'record UserResponse(...)\nstatic UserResponse toResponse(User user)',
    prompt: 'Change UserResponse so it has only id, email, and role (no password), and update toResponse to match.',
    description: 'The starter response record includes the password hash, so it would be sent to every client.',
    requirements: ['UserResponse components: Long id, String email, String role.', 'toResponse copies those three values from the User.'],
    examples: [['toResponse(user with id 1, ana@utdallas.edu, RIDER, hash)', 'UserResponse[id=1, email=ana@utdallas.edu, role=RIDER]'], ['response.toString().contains(hash)', 'false', 'The hash never leaves the server.']], constraints: ['Do not change User.'],
    starter: program('User u = new User(1L, "ana@utdallas.edu", "RIDER", "$2a$10$hash");\nSystem.out.println(toResponse(u));', { types: 'class User {\n    private final Long id; private final String email; private final String role; private final String password;\n    User(Long id, String email, String role, String password) { this.id = id; this.email = email; this.role = role; this.password = password; }\n    Long getId() { return id; }\n    String getEmail() { return email; }\n    String getRole() { return role; }\n    String getPassword() { return password; }\n}\n\nrecord UserResponse(Long id, String email, String role, String password) {}', statics: 'static UserResponse toResponse(User user) {\n    return new UserResponse(user.getId(), user.getEmail(), user.getRole(), user.getPassword());\n}' }),
    reference: program('User u = new User(1L, "ana@utdallas.edu", "RIDER", "$2a$10$hash");\nSystem.out.println(toResponse(u));', { types: 'class User {\n    private final Long id; private final String email; private final String role; private final String password;\n    User(Long id, String email, String role, String password) { this.id = id; this.email = email; this.role = role; this.password = password; }\n    Long getId() { return id; }\n    String getEmail() { return email; }\n    String getRole() { return role; }\n    String getPassword() { return password; }\n}\n\nrecord UserResponse(Long id, String email, String role) {}', statics: 'static UserResponse toResponse(User user) {\n    return new UserResponse(user.getId(), user.getEmail(), user.getRole());\n}' }),
    tests: checks('UserResponse r = Main.toResponse(new User(7L, "ben@utdallas.edu", "DRIVER", "$2a$10$secret"));\neq("id", 7L, r.id());\neq("email", "ben@utdallas.edu", r.email());\neq("role", "DRIVER", r.role());\neq("no password in JSON-ish output", false, r.toString().contains("secret"));\neq("components", 3, UserResponse.class.getRecordComponents().length);'),
    hints: ['A record\'s fields are its components, in the parentheses.', 'Remove password from the record header and from the constructor call.', 'record UserResponse(Long id, String email, String role) {}'],
  },
  practice: {
    title: 'Parse a sign-up role', signature: 'static Role parseRole(String raw)',
    prompt: 'Implement parseRole to turn client text into a Role, defaulting to RIDER and refusing self-assigned ADMIN.',
    description: 'This closes the mass-assignment hole: clients may pick rider or driver, but never admin.',
    requirements: ['null or blank: Role.RIDER.', 'Case-insensitive "rider" or "driver": RIDER or DRIVER (ignore surrounding spaces).', '"admin" in any case: throw IllegalArgumentException("Admins cannot self-register").', 'Anything else: throw IllegalArgumentException("Unknown role: " + raw).'],
    examples: [['parseRole(" Driver ")', 'DRIVER'], ['parseRole(null)', 'RIDER'], ['parseRole("Admin")', 'throws "Admins cannot self-register"']],
    constraints: ['Role is an enum with RIDER, DRIVER, ADMIN.'],
    starter: program('System.out.println(parseRole("driver"));', { types: 'enum Role { RIDER, DRIVER, ADMIN }', statics: 'static Role parseRole(String raw) {\n    return null;\n}' }),
    reference: program('System.out.println(parseRole("driver"));', { types: 'enum Role { RIDER, DRIVER, ADMIN }', statics: 'static Role parseRole(String raw) {\n    if (raw == null || raw.isBlank()) {\n        return Role.RIDER;\n    }\n    String name = raw.trim().toUpperCase();\n    if (name.equals("ADMIN")) {\n        throw new IllegalArgumentException("Admins cannot self-register");\n    }\n    if (name.equals("RIDER") || name.equals("DRIVER")) {\n        return Role.valueOf(name);\n    }\n    throw new IllegalArgumentException("Unknown role: " + raw);\n}' }),
    tests: checks('eq("driver", Role.DRIVER, Main.parseRole(" Driver "));\neq("rider", Role.RIDER, Main.parseRole("rider"));\neq("null", Role.RIDER, Main.parseRole(null));\neq("blank", Role.RIDER, Main.parseRole("  "));\nexpectThrows("admin", IllegalArgumentException.class, "Admins cannot self-register", () -> Main.parseRole("Admin"));\nexpectThrows("unknown", IllegalArgumentException.class, "Unknown role: pilot", () -> Main.parseRole("pilot"));'),
    hints: ['Normalize with trim().toUpperCase() so it matches the enum names.', 'Handle ADMIN before calling Role.valueOf, so you can give the specific message.', 'if (name.equals("RIDER") || name.equals("DRIVER")) return Role.valueOf(name);'],
  },
  sources: [{ title: 'dev.java: Records', url: J + 'records/' }, { title: 'dev.java: Enums', url: J + 'classes-objects/enums/' }],
}),

lesson({
  id: 'lambdas', title: 'Lambdas, method references & streams', file: 'config/SecurityConfig.java',
  explanation: ['A lambda like r -> r.seats() > 0 is a small unnamed function that can be passed as a value.', 'Streams chain filter, map, and collect to transform collections; SecurityConfig passes lambdas to configure each security feature.'],
  overview: 'In `http.csrf(csrf -> csrf.disable())` you hand Spring a function, and Spring calls it with the CSRF configurer. The same idea powers streams: `rides.stream().filter(r -> r.seats() > 0).map(Ride::driver).toList()`.',
  goals: ['Read and write lambdas and method references.', 'Build filter/map/collect stream pipelines to search rides.'],
  diagram: ['A stream pipeline', [['rides.stream()', 'Source: one element at a time'], ['filter(r -> r.seats() > 0)', 'Keep matching elements'], ['map(Ride::driver)', 'Transform each element'], ['toList() / count() / sum()', 'Terminal step produces the result']]],
  sections: [
    ['Lambda syntax', ['`(params) -> expression` or `params -> { statements; return x; }`. Java infers parameter types from context.', 'A lambda fits any functional interface, meaning an interface with one abstract method: Runnable, Supplier<T>, Function<T, R>, Predicate<T>.']],
    ['Method references', ['`Ride::driver` is shorthand for `r -> r.driver()`. `String::toLowerCase` means `s -> s.toLowerCase()`.', 'Use one when the lambda only calls a single existing method; otherwise write the lambda.']],
    ['Streams', ['Intermediate steps (filter, map, sorted) are lazy. Nothing runs until a terminal step (toList, count, sum, findFirst, collect).', 'Collectors.groupingBy(Ride::to, Collectors.summingInt(Ride::seats)) builds a Map in one expression.'], 'rides.stream()\n     .filter(r -> r.to().equals("UTD"))\n     .map(Ride::driver)\n     .toList();'],
    ['In CometCarpool', ['`auth -> auth.requestMatchers(...).permitAll().anyRequest().authenticated()` is one lambda. Spring calls it with an `auth` object and you chain rules onto it.', 'Ride search (UC-03, Q11 filters) maps naturally onto stream filters, or onto repository queries.']],
  ],
  misconception: 'A stream does not change the original list. filter returns a new stream, and the source list keeps every element.',
  takeaway: 'Lambdas are functions as values; streams compose them into readable data pipelines.',
  tryIt: 'Add .sorted() before .toList() in the example and predict the order.',
  example: program('List<Ride> rides = List.of(new Ride("Ana", "UTD", 3), new Ride("Ben", "Plano", 0), new Ride("Cam", "UTD", 1));\nList<String> open = rides.stream()\n        .filter(r -> r.seats() > 0)\n        .filter(r -> r.to().equals("UTD"))\n        .map(Ride::driver)\n        .toList();\nSystem.out.println(open);\nint total = rides.stream().mapToInt(Ride::seats).sum();\nSystem.out.println(total);\nFunction<Integer, Integer> twice = n -> n * 2;\nSystem.out.println(twice.apply(4));', { imports: 'import java.util.*;\nimport java.util.function.*;', types: 'record Ride(String driver, String to, int seats) {}' }),
  predict: { code: program('List<Integer> seats = List.of(4, 0, 2, 3);\nSystem.out.println(seats.stream().filter(s -> s >= 2).count());\nSystem.out.println(seats.stream().map(s -> s * 10).toList());\nSystem.out.println(seats.stream().sorted().findFirst().orElse(-1));\nRunnable r = () -> System.out.println("ran");\nSystem.out.println("before");\nr.run();'), expected: '3\n[40, 0, 20, 30]\n0\nbefore\nran\n', explanation: 'Three values are at least 2. map keeps the order. Sorting puts 0 first. Creating the Runnable prints nothing; it prints only when run() is called.' },
  guided: {
    title: 'Filter by destination', signature: 'static List<String> openDrivers(List<Ride> rides, String to)',
    prompt: 'Change openDrivers so it also filters by destination, ignoring letter case, instead of ignoring the to parameter.',
    description: 'The starter keeps rides with free seats but ignores where they go.',
    requirements: ['Keep rides with seats > 0 whose destination equals `to`, ignoring case.', 'Return driver names in the original order.'],
    examples: [['openDrivers(rides, "utd")', '[Ana, Cam]'], ['openDrivers(rides, "Plano")', '[]', 'Ben\'s Plano ride is full.']], constraints: ['Do not modify the input list.'],
    starter: program('List<Ride> rides = List.of(new Ride("Ana", "UTD", 3), new Ride("Ben", "Plano", 0), new Ride("Cam", "UTD", 1));\nSystem.out.println(openDrivers(rides, "utd"));', { types: 'record Ride(String driver, String to, int seats) {}', statics: 'static List<String> openDrivers(List<Ride> rides, String to) {\n    return rides.stream()\n            .filter(r -> r.seats() > 0)\n            .map(Ride::driver)\n            .toList();\n}' }),
    reference: program('List<Ride> rides = List.of(new Ride("Ana", "UTD", 3), new Ride("Ben", "Plano", 0), new Ride("Cam", "UTD", 1));\nSystem.out.println(openDrivers(rides, "utd"));', { types: 'record Ride(String driver, String to, int seats) {}', statics: 'static List<String> openDrivers(List<Ride> rides, String to) {\n    return rides.stream()\n            .filter(r -> r.seats() > 0)\n            .filter(r -> r.to().equalsIgnoreCase(to))\n            .map(Ride::driver)\n            .toList();\n}' }),
    tests: checks('List<Ride> rides = List.of(new Ride("Ana", "UTD", 3), new Ride("Ben", "Plano", 0), new Ride("Cam", "UTD", 1), new Ride("Dee", "Plano", 2));\neq("utd", List.of("Ana", "Cam"), Main.openDrivers(rides, "utd"));\neq("plano", List.of("Dee"), Main.openDrivers(rides, "PLANO"));\neq("nowhere", List.of(), Main.openDrivers(rides, "Frisco"));'),
    hints: ['Add another filter step to the pipeline.', 'Strings have equalsIgnoreCase.', '.filter(r -> r.to().equalsIgnoreCase(to))'],
  },
  practice: {
    title: 'Seats by destination', signature: 'static Map<String, Integer> seatsByDestination(List<Ride> rides)',
    prompt: 'Implement seatsByDestination to total the free seats for each destination, using a stream collector or a loop.',
    description: 'A heat map on the frontend shows how many seats are heading to each destination.',
    requirements: ['Key: destination exactly as stored.', 'Value: the sum of seats for that destination, including 0.', 'Empty list: empty map.'],
    examples: [['[Ana UTD 3, Ben Plano 0, Cam UTD 1]', '{UTD=4, Plano=0}'], ['[]', '{}']],
    constraints: ['Map key order does not matter.'],
    starter: program('System.out.println(seatsByDestination(List.of(new Ride("Ana", "UTD", 3))));', { types: 'record Ride(String driver, String to, int seats) {}', statics: 'static Map<String, Integer> seatsByDestination(List<Ride> rides) {\n    return Map.of();\n}' }),
    reference: program('System.out.println(seatsByDestination(List.of(new Ride("Ana", "UTD", 3))));', { imports: 'import java.util.*;\nimport java.util.stream.*;', types: 'record Ride(String driver, String to, int seats) {}', statics: 'static Map<String, Integer> seatsByDestination(List<Ride> rides) {\n    return rides.stream().collect(Collectors.groupingBy(Ride::to, Collectors.summingInt(Ride::seats)));\n}' }),
    tests: checks('List<Ride> rides = List.of(new Ride("Ana", "UTD", 3), new Ride("Ben", "Plano", 0), new Ride("Cam", "UTD", 1));\neq("mixed", Map.of("UTD", 4, "Plano", 0), Main.seatsByDestination(rides));\neq("empty", Map.of(), Main.seatsByDestination(List.of()));\neq("single", Map.of("Frisco", 2), Main.seatsByDestination(List.of(new Ride("Dee", "Frisco", 2))));'),
    hints: ['This is grouping plus summing.', 'Collectors.groupingBy takes a key function and a downstream collector; you need import java.util.stream.*;', 'rides.stream().collect(Collectors.groupingBy(Ride::to, Collectors.summingInt(Ride::seats)))'],
  },
  sources: [{ title: 'dev.java: Lambda expressions', url: J + 'lambdas/' }, { title: 'dev.java: Streams', url: J + 'api/streams/' }],
}),

lesson({
  id: 'builders', title: 'Method chaining & builders', file: 'security/JwtService.java',
  explanation: ['A fluent method returns this, so calls can chain: builder.subject(x).expiration(y).compact().', 'JwtService uses Jwts.builder() and SecurityConfig chains http.csrf(...).authorizeHttpRequests(...); both are this pattern.'],
  overview: 'Builders collect settings step by step and produce the final object at the end. `Jwts.builder().subject(email).issuedAt(now).expiration(later).signWith(key).compact()` reads like a sentence because every step returns the same builder.',
  goals: ['Write a builder whose methods return this.', 'Tell mutable builders (StringBuilder) from immutable values (String).'],
  diagram: ['Inside a chain', [['new TokenBuilder()', 'Empty settings'], ['.subject("ana")', 'Sets a field, returns this'], ['.expiresAt(1000)', 'Same object, another field'], ['.compact()', 'Builds the final String']]],
  sections: [
    ['return this', ['Each setter-like method updates a field and returns the same object, so the next call in the chain acts on it.', 'If a step returns a new object instead, earlier settings are lost.'], 'TokenBuilder subject(String s) {\n    this.subject = s;\n    return this;\n}'],
    ['Strings never change', ['String methods return new Strings. `s.toUpperCase();` on its own line does nothing useful; assign the result.', 'StringBuilder is the mutable cousin: append changes it in place and returns this.']],
    ['Reading framework chains', ['Indentation in SecurityConfig follows the nesting: http.csrf(...) and .authorizeHttpRequests(...) are calls on the same http builder.', 'http.build() at the end turns the collected settings into a SecurityFilterChain.']],
    ['In CometCarpool', ['JwtService: `.expiration(new Date(System.currentTimeMillis() + 86400000))` means expire in 24 hours. 86,400,000 ms is one day.', 'compact() is the build step: it signs the token and returns the final header.payload.signature string.']],
  ],
  misconception: 'Calling s.toUpperCase() does not change s. Strings are immutable; only the returned value is uppercase.',
  takeaway: 'Fluent APIs return this; immutable values return new objects. Know which one you are holding.',
  tryIt: 'Add a .issuer("cometcarpool") step to TokenBuilder and include it in compact().',
  example: program('String token = new TokenBuilder().subject("ana@utdallas.edu").expiresAt(1000).compact();\nSystem.out.println(token);\nStringBuilder sb = new StringBuilder("ride");\nsb.append("-").append(42).insert(0, "#");\nSystem.out.println(sb);', { types: 'class TokenBuilder {\n    private String subject = "";\n    private long expiresAt;\n\n    TokenBuilder subject(String s) {\n        this.subject = s;\n        return this;\n    }\n\n    TokenBuilder expiresAt(long t) {\n        this.expiresAt = t;\n        return this;\n    }\n\n    String compact() {\n        return subject + "|" + expiresAt;\n    }\n}' }),
  predict: { code: program('String s = "ride";\ns.toUpperCase();\nSystem.out.println(s);\ns = s.concat("-1").toUpperCase();\nSystem.out.println(s);\nStringBuilder b = new StringBuilder("a");\nb.append("b").append("c");\nSystem.out.println(b.reverse());'), expected: 'ride\nRIDE-1\ncba\n', explanation: 'The first toUpperCase result is discarded. The second chain is assigned back to s. StringBuilder mutates in place, and reverse() flips it to cba.' },
  guided: {
    title: 'Keep the chain intact', signature: 'RideQuery to(String destination)\nRideQuery minSeats(int n)',
    prompt: 'Change minSeats so it returns this instead of a new RideQuery, so earlier settings in the chain are kept.',
    description: 'new RideQuery().to("UTD").minSeats(2).describe() should print both settings, but the destination is lost.',
    requirements: ['minSeats sets the field and returns the same object.', 'describe() returns "to=" + destination + " minSeats=" + minSeats.'],
    examples: [['new RideQuery().to("UTD").minSeats(2).describe()', '"to=UTD minSeats=2"'], ['new RideQuery().minSeats(1).to("Plano").describe()', '"to=Plano minSeats=1"']], constraints: ['Do not change describe().'],
    starter: program('System.out.println(new RideQuery().to("UTD").minSeats(2).describe());', { types: 'class RideQuery {\n    private String destination = "any";\n    private int minSeats = 1;\n\n    RideQuery to(String destination) {\n        this.destination = destination;\n        return this;\n    }\n\n    RideQuery minSeats(int n) {\n        RideQuery q = new RideQuery();\n        q.minSeats = n;\n        return q;\n    }\n\n    String describe() {\n        return "to=" + destination + " minSeats=" + minSeats;\n    }\n}' }),
    reference: program('System.out.println(new RideQuery().to("UTD").minSeats(2).describe());', { types: 'class RideQuery {\n    private String destination = "any";\n    private int minSeats = 1;\n\n    RideQuery to(String destination) {\n        this.destination = destination;\n        return this;\n    }\n\n    RideQuery minSeats(int n) {\n        this.minSeats = n;\n        return this;\n    }\n\n    String describe() {\n        return "to=" + destination + " minSeats=" + minSeats;\n    }\n}' }),
    tests: checks('eq("to then seats", "to=UTD minSeats=2", new RideQuery().to("UTD").minSeats(2).describe());\neq("seats then to", "to=Plano minSeats=1", new RideQuery().minSeats(1).to("Plano").describe());\nRideQuery q = new RideQuery();\neq("same object", true, q.minSeats(3) == q);'),
    hints: ['Look at how to() is written.', 'Set the field on this object, not on a new one.', 'this.minSeats = n; return this;'],
  },
  practice: {
    title: 'A tiny SecurityConfig', signature: 'SecurityRules permit(String prefix)\nboolean allows(String path, boolean loggedIn)',
    prompt: 'Write the SecurityRules builder: permit adds a public path prefix and returns this; allows says whether a request may proceed.',
    description: 'This mirrors `requestMatchers("/api/test", "/api/users/**").permitAll().anyRequest().authenticated()`.',
    requirements: ['permit(prefix) records the prefix and returns this.', 'allows(path, loggedIn) is true when loggedIn, or when path starts with any permitted prefix.', 'Otherwise false.'],
    examples: [['new SecurityRules().permit("/api/test").permit("/api/users").allows("/api/users/login", false)', 'true'], ['... .allows("/api/rides", false)', 'false', 'Not public and not logged in.'], ['... .allows("/api/rides", true)', 'true']],
    constraints: ['Rules start with no permitted prefixes.'],
    starter: program('System.out.println(new SecurityRules().permit("/api/test").allows("/api/test", false));', { types: 'class SecurityRules {\n    SecurityRules permit(String prefix) {\n        return null;\n    }\n\n    boolean allows(String path, boolean loggedIn) {\n        return false;\n    }\n}' }),
    reference: program('System.out.println(new SecurityRules().permit("/api/test").allows("/api/test", false));', { types: 'class SecurityRules {\n    private final List<String> publicPrefixes = new ArrayList<>();\n\n    SecurityRules permit(String prefix) {\n        publicPrefixes.add(prefix);\n        return this;\n    }\n\n    boolean allows(String path, boolean loggedIn) {\n        if (loggedIn) return true;\n        for (String p : publicPrefixes) {\n            if (path.startsWith(p)) return true;\n        }\n        return false;\n    }\n}' }),
    tests: checks('SecurityRules r = new SecurityRules().permit("/api/test").permit("/api/users");\neq("public login", true, r.allows("/api/users/login", false));\neq("public test", true, r.allows("/api/test", false));\neq("private anon", false, r.allows("/api/rides", false));\neq("private logged in", true, r.allows("/api/rides", true));\neq("no rules", false, new SecurityRules().allows("/api/test", false));'),
    hints: ['You need a List<String> field to remember the prefixes.', 'permit adds to the list and returns this; allows loops over the list.', 'if (loggedIn) return true; for (String p : publicPrefixes) if (path.startsWith(p)) return true; return false;'],
  },
  sources: [{ title: 'dev.java: StringBuilder', url: J + 'strings/string-builders/' }],
}),

lesson({
  id: 'time', title: 'Dates & times with java.time', file: 'security/JwtService.java',
  explanation: ['Instant is a moment on the global timeline; LocalDateTime is a wall-clock date and time with no zone; Duration is an amount of time.', 'JWT expiry, ride departure times, and request expiry (Q9) are all time comparisons.'],
  overview: 'JwtService computes expiry with `System.currentTimeMillis() + 86400000`. java.time says the same thing more readably: `Instant.now().plus(Duration.ofHours(24))`. Ride departures need dates and times, and deadlines need isBefore/isAfter.',
  goals: ['Create and shift Instants and LocalDateTimes with Duration.', 'Compare times correctly at the boundary (expired exactly at exp).'],
  diagram: ['Pick the right time type', [['Instant', 'Machine time in UTC: token iat/exp'], ['LocalDateTime', 'Wall clock: "Nov 7, 8:30 am"'], ['Duration', '24 hours, 45 minutes'], ['isBefore / isAfter', 'Compare two points in time']]],
  sections: [
    ['Creating times', ['Instant.parse("2026-11-06T15:00:00Z"), LocalDateTime.of(2026, 11, 7, 8, 30), LocalDate.of(2026, 12, 31).', 'All java.time objects are immutable: plus and minus return new values.'], 'Instant exp = issued.plus(Duration.ofHours(24));'],
    ['Comparing and measuring', ['a.isBefore(b), a.isAfter(b), and a.equals(b) compare points in time.', 'Duration.between(a, b).toMinutes() measures the gap. It is negative when b is earlier than a.']],
    ['Testable time', ['Do not call Instant.now() deep inside logic; pass `now` in as a parameter. Then tests can use fixed times.', 'In Spring you can inject a java.time.Clock bean for the same reason.']],
    ['In CometCarpool', ['A token is expired when now is at or after exp. A ride request might expire some fixed time before departure (Q9). Cancellations may need a cutoff (Q13).', 'Store departure in the database as a timestamp; JPA maps LocalDateTime and Instant columns automatically.']],
  ],
  misconception: 'now.isBefore(expiresAt) means valid, not expired. Flipping the comparison is the classic bug, and at the exact boundary isBefore is false.',
  takeaway: 'Use Instant for moments, LocalDateTime for schedules, and pass now in so the logic is testable.',
  tryIt: 'Change Duration.ofHours(24) to Duration.ofMinutes(90) and predict the printed expiry.',
  example: program('Instant issued = Instant.parse("2026-11-06T15:00:00Z");\nInstant expires = issued.plus(Duration.ofHours(24));\nSystem.out.println(expires);\nSystem.out.println(Duration.between(issued, expires).toMillis());\nLocalDateTime departs = LocalDateTime.of(2026, 11, 7, 8, 30);\nSystem.out.println(departs.minusMinutes(45));', { imports: 'import java.time.*;' }),
  predict: { code: program('Instant now = Instant.parse("2026-11-06T23:30:00Z");\nInstant exp = Instant.parse("2026-11-07T00:00:00Z");\nSystem.out.println(now.isBefore(exp));\nSystem.out.println(Duration.between(now, exp).toMinutes());\nLocalDate d = LocalDate.of(2026, 12, 31);\nSystem.out.println(d.plusDays(1));\nSystem.out.println(d.getDayOfWeek());', { imports: 'import java.time.*;' }), expected: 'true\n30\n2027-01-01\nTHURSDAY\n', explanation: '23:30 is 30 minutes before midnight. plusDays rolls over into the new year. Dec 31, 2026 falls on a Thursday.' },
  guided: {
    title: 'Fix the expiry check', signature: 'static boolean isExpired(Instant expiresAt, Instant now)',
    prompt: 'Change isExpired so it returns true when now is at or after expiresAt; the starter has the comparison backwards.',
    description: 'A token that expired yesterday is reported as valid, and a fresh one as expired.',
    requirements: ['now before expiresAt: false.', 'now equal to expiresAt: true.', 'now after expiresAt: true.'],
    examples: [['expiresAt 12:00, now 11:59', 'false'], ['expiresAt 12:00, now 12:00', 'true', 'Expired exactly at exp.'], ['expiresAt 12:00, now 12:01', 'true']], constraints: ['Use Instant comparison methods.'],
    starter: program('System.out.println(isExpired(Instant.parse("2026-11-06T12:00:00Z"), Instant.parse("2026-11-06T12:01:00Z")));', { imports: 'import java.time.*;', statics: 'static boolean isExpired(Instant expiresAt, Instant now) {\n    return now.isBefore(expiresAt);\n}' }),
    reference: program('System.out.println(isExpired(Instant.parse("2026-11-06T12:00:00Z"), Instant.parse("2026-11-06T12:01:00Z")));', { imports: 'import java.time.*;', statics: 'static boolean isExpired(Instant expiresAt, Instant now) {\n    return !now.isBefore(expiresAt);\n}' }),
    tests: checks('Instant exp = Instant.parse("2026-11-06T12:00:00Z");\neq("before", false, Main.isExpired(exp, exp.minusSeconds(60)));\neq("equal", true, Main.isExpired(exp, exp));\neq("after", true, Main.isExpired(exp, exp.plusSeconds(60)));', { imports: 'import java.time.*;' }),
    hints: ['Expired means "not before".', 'Negate the comparison, or use isAfter combined with equals.', 'return !now.isBefore(expiresAt);'],
  },
  practice: {
    title: 'Cancellation cutoff', signature: 'static boolean canCancel(LocalDateTime departure, LocalDateTime now)',
    prompt: 'Implement canCancel so riders may cancel only when now is at least 2 hours before departure.',
    description: 'A proposed rule for P2 question Q13: late cancellations hurt drivers, so the app stops them inside 2 hours.',
    requirements: ['true when now is 2 hours or more before departure.', 'false inside the 2-hour window, at departure, or after it.'],
    examples: [['departure 10:00, now 07:30', 'true'], ['departure 10:00, now 08:00', 'true', 'Exactly 2 hours before is allowed.'], ['departure 10:00, now 08:01', 'false']],
    constraints: ['Use java.time; no manual minute math on strings.'],
    starter: program('System.out.println(canCancel(LocalDateTime.of(2026, 11, 7, 10, 0), LocalDateTime.of(2026, 11, 7, 7, 30)));', { imports: 'import java.time.*;', statics: 'static boolean canCancel(LocalDateTime departure, LocalDateTime now) {\n    return false;\n}' }),
    reference: program('System.out.println(canCancel(LocalDateTime.of(2026, 11, 7, 10, 0), LocalDateTime.of(2026, 11, 7, 7, 30)));', { imports: 'import java.time.*;', statics: 'static boolean canCancel(LocalDateTime departure, LocalDateTime now) {\n    return !now.isAfter(departure.minusHours(2));\n}' }),
    tests: checks('LocalDateTime dep = LocalDateTime.of(2026, 11, 7, 10, 0);\neq("2.5h before", true, Main.canCancel(dep, dep.minusMinutes(150)));\neq("exactly 2h", true, Main.canCancel(dep, dep.minusHours(2)));\neq("1h59 before", false, Main.canCancel(dep, dep.minusMinutes(119)));\neq("at departure", false, Main.canCancel(dep, dep));\neq("after", false, Main.canCancel(dep, dep.plusHours(1)));\neq("day before", true, Main.canCancel(dep, dep.minusDays(1)));', { imports: 'import java.time.*;' }),
    hints: ['Compute the cutoff moment first: departure minus 2 hours.', 'Cancelling is allowed when now is not after the cutoff.', 'return !now.isAfter(departure.minusHours(2));'],
  },
  sources: [{ title: 'dev.java: Date and time', url: J + 'date-time/' }],
}),

];
